export const FEAT_SPELL_DETAILS = {
  "blade-ward": {"time":"Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 minute","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:blade-ward","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "chill-touch": {"time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","desc":"Channeling the chill of the grave, make a melee spell attack against a target within reach. On a hit, the target takes 1d10 Necrotic damage, and it can’t regain Hit Points until the end of your next turn.","higher":"Cantrip Upgrade. The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10).","verbatim":true,"source":"SRD 5.2.1 p.115","checked":true,"note":""},
  "druidcraft": {"time":"Action","range":"30 feet","components":"V, S","duration":"Instantaneous","desc":"Whispering to the spirits of nature, you create one of the following effects within range.\n\nWeather Sensor. You create a Tiny, harmless sensory effect that predicts what the weather will be at your location for the next 24 hours. The effect might manifest as a golden orb for clear skies, a cloud for rain, falling snowflakes for snow, and so on. This effect persists for 1 round.\n\nBloom. You instantly make a flower blossom, a seed pod open, or a leaf bud bloom.\n\nSensory Effect. You create a harmless sensory effect, such as falling leaves, spectral dancing fairies, a gentle breeze, the sound of an animal, or the faint odor of skunk. The effect must fit in a 5-foot Cube.\n\nFire Play. You light or snuff out a candle, a torch, or a campfire.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.126","checked":true,"note":""},
  "friends": {"time":"Action","range":"10 feet","components":"S, M","duration":"Concentration, up to 1 minute","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:friends","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "mind-sliver": {"time":"Action","range":"60 feet","components":"V","duration":"1 round","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:mind-sliver","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "minor-illusion": {"time":"Action","range":"30 feet","components":"S, M (a bit of fleece)","duration":"1 minute","desc":"You create a sound or an image of an object within range that lasts for the duration. See the descriptions below for the effects of each. The illusion ends if you cast this spell again.\n\nIf a creature takes a Study action to examine the sound or image, the creature can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the illusion becomes faint to the creature.\n\nSound. If you create a sound, its volume can range from a whisper to a scream. It can be your voice, someone else’s voice, a lion’s roar, a beating of drums, or any other sound you choose. The sound continues unabated throughout the duration, or you can make discrete sounds at different times before the spell ends.\n\nImage. If you create an image of an object—such as a chair, muddy footprints, or a small chest—it must be no larger than a 5-foot Cube. The image can’t create sound, light, smell, or any other sensory effect. Physical interaction with the image reveals it to be an illusion, since things can pass through it.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.149","checked":true,"note":""},
  "produce-flame": {"time":"Bonus Action","range":"Self","components":"V, S","duration":"10 minutes","desc":"A flickering flame appears in your hand and remains there for the duration. While there, the flame emits no heat and ignites nothing, and it sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. The spell ends if you cast it again.\n\nUntil the spell ends, you can take a Magic action to hurl fire at a creature or an object within 60 feet of you. Make a ranged spell attack. On a hit, the target takes 1d8 Fire damage.","higher":"Cantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).","verbatim":true,"source":"SRD 5.2.1 p.156","checked":true,"note":""},
  "sacred-flame": {"time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","desc":"Flame-like radiance descends on a creature that you can see within range. The target must succeed on a Dexterity saving throw or take 1d8 Radiant damage. The target gains no benefit from Half Cover or Three-Quarters Cover for this save.","higher":"Cantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).","verbatim":true,"source":"SRD 5.2.1 p.159","checked":true,"note":""},
  "shillelagh": {"time":"Bonus Action","range":"Self","components":"V, S, M (mistletoe)","duration":"1 minute","desc":"A Club or Quarterstaff you are holding is imbued with nature’s power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon’s damage die becomes a d8. If the attack deals damage, it can be Force damage or the weapon’s normal damage type (your choice).\n\nThe spell ends early if you cast it again or if you let go of the weapon.","higher":"Cantrip Upgrade. The damage die changes when you reach levels 5 (d10), 11 (d12), and 17 (2d6).","verbatim":true,"source":"SRD 5.2.1 p.162","checked":true,"note":""},
  "sorcerous-burst": {"time":"Action","range":"120 feet","components":"V, S","duration":"Instantaneous","desc":"You cast sorcerous energy at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 damage of a type you choose: Acid, Cold, Fire, Lightning, Poison, Psychic, or Thunder.\n\nIf you roll an 8 on a d8 for this spell, you can roll another d8, and add it to the damage. When you cast this spell, the maximum number of these d8s you can add to the spell’s damage equals your spellcasting ability modifier.","higher":"Cantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).","verbatim":true,"source":"SRD 5.2.1 p.163","checked":true,"note":""},
  "starry-wisp": {"time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","desc":"You launch a mote of light at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 Radiant damage, and until the end of your next turn, it emits Dim Light in a 10-foot radius and can’t benefit from the Invisible condition.","higher":"Cantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).","verbatim":true,"source":"SRD 5.2.1 p.165","checked":true,"note":""},
  "thaumaturgy": {"time":"Action","range":"30 feet","components":"V","duration":"Up to 1 minute","desc":"You manifest a minor wonder within range. You create one of the effects below within range. If you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time.\n\nAltered Eyes. You alter the appearance of your eyes for 1 minute.\n\nBooming Voice. Your voice booms up to three times as loud as normal for 1 minute. For the duration, you have Advantage on Charisma (Intimidation) checks.\n\nFire Play. You cause flames to flicker, brighten, dim, or change color for 1 minute.\n\nInvisible Hand. You instantaneously cause an unlocked door or window to fly open or slam shut.\n\nPhantom Sound. You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers.\n\nTremors. You cause harmless tremors in the ground for 1 minute.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.169","checked":true,"note":""},
  "toll-the-dead": {"time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:toll-the-dead","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "word-of-radiance": {"time":"Action","range":"Self","components":"V, M","duration":"Instantaneous","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:word-of-radiance","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "animal-friendship": {"time":"Action","range":"30 feet","components":"V, S, M (a morsel of food)","duration":"24 hours","desc":"Target a Beast that you can see within range. The target must succeed on a Wisdom saving throw or have the Charmed condition for the duration. If you or one of your allies deals damage to the target, the spells ends.","higher":"Using a Higher-Level Spell Slot. You can target one additional Beast for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.107","checked":true,"note":""},
  "armor-of-agathys": {"time":"Bonus Action","range":"Self","components":"V, S, M","duration":"1 hour","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:armor-of-agathys","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "bane": {"time":"Action","range":"30 feet","components":"V, S, M (a drop of blood)","duration":"Concentration, up to 1 minute","desc":"Up to three creatures of your choice that you can see within range must each make a Charisma saving throw. Whenever a target that fails this save makes an attack roll or a saving throw before the spell ends, the target must subtract 1d4 from the attack roll or save.","higher":"Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.112","checked":true,"note":""},
  "bless": {"time":"Action","range":"30 feet","components":"V, S, M (a Holy Symbol worth 5+ GP)","duration":"Concentration, up to 1 minute","desc":"You bless up to three creatures within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target adds 1d4 to the attack roll or save.","higher":"Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.113","checked":true,"note":""},
  "burning-hands": {"time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","desc":"A thin sheet of flames shoots forth from you. Each creature in a 15-foot Cone makes a Dexterity saving throw, taking 3d6 Fire damage on a failed save or half as much damage on a successful one.\n\nFlammable objects in the Cone that aren’t being worn or carried start burning.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.114","checked":true,"note":""},
  "charm-person": {"time":"Action","range":"30 feet","components":"V, S","duration":"1 hour","desc":"One Humanoid you can see within range makes a Wisdom saving throw. It does so with Advantage if you or your allies are fighting it. On a failed save, the target has the Charmed condition until the spell ends or until you or your allies damage it. The Charmed creature is Friendly to you. When the spell ends, the target knows it was Charmed by you.","higher":"Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.115","checked":true,"note":""},
  "chromatic-orb": {"time":"Action","range":"90 feet","components":"V, S, M (a diamond worth 50+ GP)","duration":"Instantaneous","desc":"You hurl an orb of energy at a target within range. Choose Acid, Cold, Fire, Lightning, Poison, or Thunder for the type of orb you create, and then make a ranged spell attack against the target. On a hit, the target takes 3d8 damage of the chosen type.\n\nIf you roll the same number on two or more of the d8s, the orb leaps to a different target of your choice within 30 feet of the target. Make an attack roll against the new target, and make a new damage roll. The orb can’t leap again unless you cast the spell with a level 2+ spell slot.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 1. The orb can leap a maximum number of times equal to the level of the slot expended, and a creature can be targeted only once by each casting of this spell.","verbatim":true,"source":"SRD 5.2.1 p.115","checked":true,"note":""},
  "color-spray": {"time":"Action","range":"Self","components":"V, S, M (a pinch of colorful sand)","duration":"Instantaneous","desc":"You launch a dazzling array of flashing, colorful light. Each creature in a 15-foot Cone originating from you must succeed on a Constitution saving throw or have the Blinded condition until the end of your next turn.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.116","checked":true,"note":""},
  "command": {"time":"Action","range":"60 feet","components":"V","duration":"Instantaneous","desc":"You speak a one-word command to a creature you can see within range. The target must succeed on a Wisdom saving throw or follow the command on its next turn. Choose the command from these options:\n\nApproach. The target moves toward you by the shortest and most direct route, ending its turn if it moves within 5 feet of you.\n\nDrop. The target drops whatever it is holding and then ends its turn.\n\nFlee. The target spends its turn moving away from you by the fastest available means.\n\nGrovel. The target has the Prone condition and then ends its turn.\n\nHalt. On its turn, the target doesn’t move and takes no action or Bonus Action. Using a Higher-Level Spell Slot. You can affect\n\none additional creature for each spell slot level above 1.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.116","checked":true,"note":""},
  "compelled-duel": {"time":"Bonus Action","range":"30 feet","components":"V","duration":"Concentration, up to 1 minute","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:compelled-duel","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "comprehend-languages": {"time":"Action or Ritual","range":"Self","components":"V, S, M (a pinch of soot and salt)","duration":"1 hour","desc":"For the duration, you understand the literal meaning of any language that you hear or see signed. You also understand any written language that you see, but you must be touching the surface on which the words are written. It takes about 1 minute to read one page of text. This spell doesn’t decode symbols or secret messages.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.117","checked":true,"note":""},
  "create-or-destroy-water": {"time":"Action","range":"30 feet","components":"V, S, M (a mix of water and sand)","duration":"Instantaneous","desc":"You do one of the following:\n\nCreate Water. You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot Cube within range, extinguishing exposed flames there.\n\nDestroy Water. You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot Cube within range. Using a Higher-Level Spell Slot. You create or\n\ndestroy 10 additional gallons of water, or the size of the Cube increases by 5 feet, for each spell slot level above 1.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.121","checked":true,"note":""},
  "detect-evil-and-good": {"time":"Action","range":"Self","components":"V, S","duration":"Concentration, up to 10 minutes","desc":"For the duration, you sense the location of any Aberration, Celestial, Elemental, Fey, Fiend, or Undead within 30 feet of yourself. You also sense whether the Hallow spell is active there and, if so, where.\n\nThe spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.123","checked":true,"note":""},
  "detect-poison-and-disease": {"time":"Action or Ritual","range":"Self","components":"V, S, M (a yew leaf)","duration":"Concentration, up to 10 minutes","desc":"For the duration, you sense the location of poisons, poisonous or venomous creatures, and magical contagions within 30 feet of yourself. You sense the kind of poison, creature, or contagion in each case.\n\nThe spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.123","checked":true,"note":""},
  "dissonant-whispers": {"time":"Action","range":"60 feet","components":"V","duration":"Instantaneous","desc":"One creature of your choice that you can see within range hears a discordant melody in its mind. The target makes a Wisdom saving throw. On a failed save, it takes 3d6 Psychic damage and must immediately use its Reaction, if available, to move as far away from you as it can, using the safest route. On a successful save, the target takes half as much damage only.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.124","checked":true,"note":""},
  "entangle": {"time":"Action","range":"90 feet","components":"V, S","duration":"Concentration, up to 1 minute","desc":"Grasping plants sprout from the ground in a 20-foot square within range. For the duration, these plants turn the ground in the area into Difficult Terrain. They disappear when the spell ends.\n\nEach creature (other than you) in the area when you cast the spell must succeed on a Strength saving throw or have the Restrained condition until the spell ends. A Restrained creature can take an action to make a Strength (Athletics) check against your spell save DC. On a success, it frees itself from the grasping plants and is no longer Restrained by them.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.128","checked":true,"note":""},
  "find-familiar": {"time":"1 hour or Ritual","range":"10 feet","components":"V, S, M (burning incense worth 10+ GP, which the spell consumes)","duration":"Instantaneous","desc":"You gain the service of a familiar, a spirit that takes an animal form you choose: Bat, Cat, Frog, Hawk,\n\nLizard, Octopus, Owl, Rat, Raven, Spider, Weasel,\n\nor another Beast that has a Challenge Rating of 0. Appearing in an unoccupied space within range, the familiar has the statistics of the chosen form (see “Monsters”), though it is a Celestial, Fey, or Fiend (your choice) instead of a Beast. Your familiar acts independently of you, but it obeys your commands.\n\nTelepathic Connection. While your familiar is within 100 feet of you, you can communicate with it telepathically. Additionally, as a Bonus Action, you can see through the familiar’s eyes and hear what it hears until the start of your next turn, gaining the benefits of any special senses it has.\n\nFinally, when you cast a spell with a range of touch, your familiar can deliver the touch. Your familiar must be within 100 feet of you, and it must take a Reaction to deliver the touch when you cast the spell.\n\nCombat. The familiar is an ally to you and your allies. It rolls its own Initiative and acts on its own turn. A familiar can’t attack, but it can take other actions as normal.\n\nDisappearance of the Familiar. When the familiar drops to 0 Hit Points, it disappears. It reappears after you cast this spell again. As a Magic action, you can temporarily dismiss the familiar to a pocket dimension. Alternatively, you can dismiss it forever. As a Magic action while it is temporarily dismissed, you can cause it to reappear in an unoccupied space within 30 feet of you. Whenever the familiar drops to 0 Hit Points or disappears into the pocket dimension, it leaves behind in its space anything it was wearing or carrying.\n\nOne Familiar Only. You can’t have more than one familiar at a time. If you cast this spell while you have a familiar, you instead cause it to adopt a new eligible form.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.130","checked":true,"note":""},
  "fog-cloud": {"time":"Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 1 hour","desc":"You create a 20-foot-radius Sphere of fog centered on a point within range. The Sphere is Heavily Obscured. It lasts for the duration or until a strong wind (such as one created by Gust of Wind) disperses it.","higher":"Using a Higher-Level Spell Slot. The fog’s radius increases by 20 feet for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.133","checked":true,"note":""},
  "goodberry": {"time":"Action","range":"Self","components":"V, S, M (a sprig of mistletoe)","duration":"24 hours","desc":"Ten berries appear in your hand and are infused with magic for the duration. A creature can take a Bonus Action to eat one berry. Eating a berry restores 1 Hit Point, and the berry provides enough nourishment to sustain a creature for one day.\n\nUneaten berries disappear when the spell ends.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.137","checked":true,"note":""},
  "guiding-bolt": {"time":"Action","range":"120 feet","components":"V, S","duration":"1 round","desc":"You hurl a bolt of light toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 4d6 Radiant damage, and the next attack roll made against it before the end of your next turn has Advantage.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.138","checked":true,"note":""},
  "healing-word": {"time":"Bonus Action","range":"60 feet","components":"V","duration":"Instantaneous","desc":"A creature of your choice that you can see within range regains Hit Points equal to 2d4 plus your spellcasting ability modifier.","higher":"Using a Higher-Level Spell Slot. The healing increases by 2d4 for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.139","checked":true,"note":""},
  "heroism": {"time":"Action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 minute","desc":"A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to the Frightened condition and gains Temporary Hit Points equal to your spellcasting ability modifier at the start of each of its turns.","higher":"Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.140","checked":true,"note":""},
  "hex": {"time":"Bonus Action","range":"90 feet","components":"V, S, M (the petrified eye of a newt)","duration":"Concentration, up to 1 hour","desc":"You place a curse on a creature that you can see within range. Until the spell ends, you deal an extra 1d6 Necrotic damage to the target whenever you hit it with an attack roll. Also, choose one ability when you cast the spell. The target has Disadvantage on ability checks made with the chosen ability.\n\nIf the target drops to 0 Hit Points before this spell ends, you can take a Bonus Action on a later turn to curse a new creature.","higher":"Using a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 2 (up to 4 hours), 3–4 (up to 8 hours), or 5+ (24 hours).","verbatim":true,"source":"SRD 5.2.1 p.140","checked":true,"note":""},
  "hunter-s-mark": {"time":"Bonus Action","range":"90 feet","components":"V","duration":"Concentration, up to 1 hour","desc":"You magically mark one creature you can see within range as your quarry. Until the spell ends, you deal an extra 1d6 Force damage to the target whenever you hit it with an attack roll. You also have Advantage on any Wisdom (Perception or Survival) check you make to find it.\n\nIf the target drops to 0 Hit Points before this spell ends, you can take a Bonus Action to move the mark to a new creature you can see within range.","higher":"Using a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 3–4 (up to 8 hours) or 5+ (up to 24 hours).","verbatim":true,"source":"SRD 5.2.1 p.141","checked":true,"note":""},
  "ice-knife": {"time":"Action","range":"60 feet","components":"S, M (a drop of water or a piece of ice)","duration":"Instantaneous","desc":"You create a shard of ice and fling it at one creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 Piercing damage. Hit or miss, the shard then explodes. The target and each creature within 5 feet of it must succeed on a Dexterity saving throw or take 2d6 Cold damage.","higher":"Using a Higher-Level Spell Slot. The Cold damage increases by 1d6 for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.141","checked":true,"note":""},
  "illusory-script": {"time":"1 minute or Ritual","range":"Touch","components":"S, M (ink worth 10+ GP, which the spell consumes)","duration":"10 days","desc":"You write on parchment, paper, or another suitable material and imbue it with an illusion that lasts for the duration. To you and any creatures you designate when you cast the spell, the writing appears normal, seems to be written in your hand, and conveys whatever meaning you intended when you wrote the text. To all others, the writing appears as if it were written in an unknown or magical script that is unintelligible. Alternatively, the illusion can alter the meaning, handwriting, and language of the text, though the language must be one you know.\n\nIf the spell is dispelled, the original script and the illusion both disappear.\n\nA creature that has Truesight can read the hidden message.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.142","checked":true,"note":""},
  "inflict-wounds": {"time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","desc":"A creature you touch makes a Constitution saving throw, taking 2d10 Necrotic damage on a failed save or half as much damage on a successful one.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.143","checked":true,"note":""},
  "mage-armor": {"time":"Action","range":"Touch","components":"V, S, M (a piece of cured leather)","duration":"8 hours","desc":"You touch a willing creature who isn’t wearing armor. Until the spell ends, the target’s base AC becomes 13 plus its Dexterity modifier. The spell ends early if the target dons armor.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.145","checked":true,"note":""},
  "magic-missile": {"time":"Action","range":"120 feet","components":"V, S","duration":"Instantaneous","desc":"You create three glowing darts of magical force. Each dart strikes a creature of your choice that you can see within range. A dart deals 1d4 + 1 Force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several.","higher":"Using a Higher-Level Spell Slot. The spell creates one more dart for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.146","checked":true,"note":""},
  "protection-from-evil-and-good": {"time":"Action","range":"Touch","components":"V, S, M (a flask of Holy Water worth 25+ GP, which the spell consumes)","duration":"Concentration up to 10 minutes","desc":"Until the spell ends, one willing creature you touch is protected against creatures that are Aberrations, Celestials, Elementals, Fey, Fiends, or Undead. The protection grants several benefits. Creatures of those types have Disadvantage on attack rolls against the target. The target also can’t be possessed by or gain the Charmed or Frightened conditions from them. If the target is already possessed, Charmed, or Frightened by such a creature, the target has Advantage on any new saving throw against the relevant effect.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.157","checked":true,"note":""},
  "ray-of-sickness": {"time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","desc":"You shoot a greenish ray at a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 2d8 Poison damage and has the Poisoned condition until the end of your next turn.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.158","checked":true,"note":""},
  "shield-of-faith": {"time":"Bonus Action","range":"60 feet","components":"V, S, M (a prayer scroll)","duration":"Concentration, up to 10 minutes","desc":"A shimmering field surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.162","checked":true,"note":""},
  "silent-image": {"time":"Action","range":"60 feet","components":"V, S, M (a bit of fleece)","duration":"Concentration, up to 10 minutes","desc":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15-foot Cube. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn’t accompanied by sound, smell, or other sensory effects.\n\nAs a Magic action, you can cause the image to move to any spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking.\n\nPhysical interaction with the image reveals it to be an illusion, since things can pass through it. A creature that takes a Study action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.162","checked":true,"note":""},
  "sleep": {"time":"Action","range":"60 feet","components":"V, S, M (a pinch of sand or rose petals)","duration":"Concentration, up to 1 minute","desc":"Each creature of your choice in a 5-foot-radius Sphere centered on a point within range must succeed on a Wisdom saving throw or have the Incapacitated condition until the end of its next turn, at which point it must repeat the save. If the target fails the second save, the target has the Unconscious condition for the duration. The spell ends on a target if it takes damage or someone within 5 feet of it takes an action to shake it out of the spell’s effect.\n\nCreatures that don’t sleep, such as elves, or that have Immunity to the Exhaustion condition automatically succeed on saves against this spell.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.163","checked":true,"note":""},
  "speak-with-animals": {"time":"Action or Ritual","range":"Self","components":"V, S","duration":"10 minutes","desc":"For the duration, you can comprehend and verbally communicate with Beasts, and you can use any of the Influence action’s skill options with them.\n\nMost Beasts have little to say about topics that don’t pertain to survival or companionship, but at minimum, a Beast can give you information about nearby locations and monsters, including whatever it has perceived within the past day.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.164","checked":true,"note":""},
  "tasha-s-hideous-laughter": {"time":"Action","range":"30 feet","components":"V, S, M (a tart and a feather)","duration":"Concentration, up to 1 minute","desc":"One creature of your choice that you can see within range makes a Wisdom saving throw. On a failed save, it has the Prone and Incapacitated conditions for the duration. During that time, it laughs uncontrollably if it’s capable of laughter, and it can’t end the Prone condition on itself.\n\nAt the end of each of its turns and each time it takes damage, it makes another Wisdom saving throw. The target has Advantage on the save if the save is triggered by damage. On a successful save, the spell ends.","higher":"Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","verbatim":true,"source":"SRD 5.2.1 p.140","checked":true,"note":""},
  "tenser-s-floating-disk": {"time":"Action or Ritual","range":"30 feet","components":"V, S, M (a drop of mercury)","duration":"1 hour","desc":"This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground.\n\nThe disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. It can move across uneven terrain, up or down stairs, slopes and the like, but it can’t cross an elevation change of 10 feet or more. For example, the disk can’t move across a 10-foot-deep pit, nor could it leave such a pit if it was created at the bottom.\n\nIf you move more than 100 feet from the disk (typically because it can’t move around an obstacle to follow you), the spell ends.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.133","checked":true,"note":""},
  "unseen-servant": {"time":"Action or Ritual","range":"60 feet","components":"V, S, M (a bit of string and of wood)","duration":"1 hour","desc":"This spell creates an Invisible, mindless, shapeless, Medium force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 Hit Point, and a Strength of 2, and it can’t attack. If it drops to 0 Hit Points, the spell ends.\n\nOnce on each of your turns as a Bonus Action, you can mentally command the servant to move up to 15 feet and interact with an object. The servant can perform simple tasks that a human could do, such as fetching things, cleaning, mending, folding clothes, lighting fires, serving food, and pouring drinks. Once you give the command, the servant performs the task to the best of its ability until it completes the task, then waits for your next command.\n\nIf you command the servant to perform a task that would move it more than 60 feet away from you, the spell ends.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.171","checked":true,"note":""},
  "witch-bolt": {"time":"Action","range":"60 feet","components":"V, S, M","duration":"Concentration, up to 1 minute","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:witch-bolt","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "wrathful-smite": {"time":"Bonus Action(*)","range":"Self","components":"V","duration":"1 minute","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:wrathful-smite","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "animal-messenger": {"time":"Action or Ritual","range":"30 feet","components":"V, S, M (a morsel of food)","duration":"24 hours","desc":"A Tiny Beast of your choice that you can see within range must succeed on a Charisma saving throw, or it attempts to deliver a message for you (if the target’s Challenge Rating isn’t 0, it automatically succeeds). You specify a location you have visited and a recipient who matches a general description, such as “a person dressed in the uniform of the town guard” or “a red-haired dwarf wearing a pointed hat.” You also communicate a message of up to twenty-five words. The Beast travels for the duration toward the specified location, covering about 25 miles per 24 hours or 50 miles if the Beast can fly.\n\nWhen the Beast arrives, it delivers your message to the creature that you described, mimicking your communication. If the Beast doesn’t reach its destination before the spell ends, the message is lost, and the Beast returns to where you cast the spell.","higher":"Using a Higher-Level Spell Slot. The spell’s duration increases by 48 hours for each spell slot level above 2.","verbatim":true,"source":"SRD 5.2.1 p.108","checked":true,"note":""},
  "beast-sense": {"time":"Action or Ritual","range":"Touch","components":"S","duration":"Concentration, up to 1 hour","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:beast-sense","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "blindness-deafness": {"time":"Action","range":"120 feet","components":"V","duration":"1 minute","desc":"One creature that you can see within range must succeed on a Constitution saving throw, or it has the Blinded or Deafened condition (your choice) for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.","higher":"Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 2.","verbatim":true,"source":"SRD 5.2.1 p.113","checked":true,"note":""},
  "calm-emotions": {"time":"Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","desc":"Each Humanoid in a 20-foot-radius Sphere centered on a point you choose within range must succeed on a Charisma saving throw or be affected by one of the following effects (choose for each creature):\n\n• The creature has Immunity to the Charmed and Frightened conditions until the spell ends. If the creature was already Charmed or Frightened, those conditions are suppressed for the duration.\n• The creature becomes Indifferent about creatures of your choice that it’s Hostile toward. This indifference ends if the target takes damage or witnesses its allies taking damage. When the spell ends, the creature’s attitude returns to normal.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.114","checked":true,"note":""},
  "cloud-of-daggers": {"time":"Action","range":"60 feet","components":"V, S, M","duration":"Concentration, up to 1 minute","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:cloud-of-daggers","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "crown-of-madness": {"time":"Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 1 minute","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:crown-of-madness","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "darkness": {"time":"Action","range":"60 feet","components":"V, M (bat fur and a piece of coal)","duration":"Concentration, up to 10 minutes","desc":"For the duration, magical Darkness spreads from a point within range and fills a 15-foot-radius Sphere. Darkvision can’t see through it, and nonmagical light can’t illuminate it.\n\nAlternatively, you cast the spell on an object that isn’t being worn or carried, causing the Darkness to fill a 15-foot Emanation originating from that object. Covering that object with something opaque, such as a bowl or helm, blocks the Darkness.\n\nIf any of this spell’s area overlaps with an area of Bright Light or Dim Light created by a spell of level 2 or lower, that other spell is dispelled.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.122","checked":true,"note":""},
  "detect-thoughts": {"time":"Action","range":"Self","components":"V, S, M (1 Copper Piece)","duration":"Concentration, up to 1 minute","desc":"You activate one of the effects below. Until the spell ends, you can activate either effect as a Magic action on your later turns.\n\nSense Thoughts. You sense the presence of thoughts within 30 feet of yourself that belong to creatures that know languages or are telepathic. You don’t read the thoughts, but you know that a thinking creature is present.\n\nThe spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.\n\nRead Thoughts. Target one creature you can see within 30 feet of yourself or one creature within 30 feet of yourself that you detected with the Sense Thoughts option. You learn what is most on the target’s mind right now. If the target doesn’t know any languages and isn’t telepathic, you learn nothing.\n\nAs a Magic action on your next turn, you can try to probe deeper into the target’s mind. If you probe deeper, the target makes a Wisdom saving throw. On a failed save, you discern the target’s reasoning, emotions, and something that looms large in its mind (such as a worry, love, or hate). On a successful save, the spell ends. Either way, the target knows that you are probing into its mind, and until you shift your attention away from the target’s mind, the target can take an action on its turn to make an Intelligence (Arcana) check against your spell save DC, ending the spell on a success.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.123","checked":true,"note":""},
  "find-steed": {"time":"Action","range":"30 feet","components":"V, S","duration":"Instantaneous","desc":"You summon an otherworldly being that appears as a loyal steed in an unoccupied space of your choice within range. This creature uses the Otherworldly\n\nSteed stat block. If you already have a steed from\n\nthis spell, the steed is replaced by the new one.\n\nThe steed resembles a Large, rideable animal of your choice, such as a horse, a camel, a dire wolf, or an elk. Whenever you cast the spell, choose the steed’s creature type—Celestial, Fey, or Fiend— which determines certain traits in the stat block.\n\nCombat. The steed is an ally to you and your allies. In combat, it shares your Initiative count, and it functions as a controlled mount while you ride it (as defined in the rules on mounted combat). If you have the Incapacitated condition, the steed takes its turn immediately after yours and acts independently, focusing on protecting you.\n\nDisappearance of the Steed. The steed disappears if it drops to 0 Hit Points or if you die. When it disappears, it leaves behind anything it was wearing or carrying. If you cast this spell again, you decide whether you summon the steed that disappeared or a different one.\n\nOtherworldly Steed\nLarge Celestial, Fey, or Fiend (Your Choice), Neutral\nAC 10 + 1 per spell level\nHP 5 + 10 per spell level (the steed has a number of Hit\nDice [d10s] equal to the spell’s level)\nSpeed 60 ft., Fly 60 ft. (requires level 4+ spell)\nMOD | SAVE | MOD | SAVE | MOD | SAVE\nStr 18 | +4 | +4    dex 12 | +1 | +1 | con 14 | +2 | +2\nint 6 | −2 | −2 | WiS 12 | +1 | +1 | chA 8 | −1 | −1\nSenses Passive Perception 11\nLanguages Telepathy 1 mile (works only with you)\nCR None (XP 0; PB equals your Proficiency Bonus)\nTraits\nLife Bond. When you regain Hit Points from a level 1+\nspell, the steed regains the same number of Hit Points if\nyou’re within 5 feet of it.\nActions\nOtherworldly Slam. Melee Attack Roll: Bonus equals\nyour spell attack modifier, reach 5 ft. Hit: 1d8 plus the\nspell’s level of Radiant (Celestial), Psychic (Fey), or Ne-\ncrotic (Fiend) damage.\nBonus Actions\nFell Glare (Fiend Only; Recharges after a Long Rest).\nWisdom Saving Throw: DC equals your spell save DC,\none creature within 60 feet the steed can see. Failure:\nThe target has the Frightened condition until the end of\nyour next turn.\nFey Step (Fey Only; Recharges after a Long Rest). The\nsteed teleports, along with its rider, to an unoccupied\nspace of your choice up to 60 feet away from itself.\nHealing Touch (Celestial Only; Recharges after a Long\nRest). One creature within 5 feet of the steed regains a\nnumber of Hit Points equal to 2d8 plus the spell’s level.","higher":"Using a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.","verbatim":true,"source":"SRD 5.2.1 p.130","checked":true,"note":""},
  "find-traps": {"time":"Action","range":"120 feet","components":"V, S","duration":"Instantaneous","desc":"You sense any trap within range that is within line of sight. A trap, for the purpose of this spell, includes any object or mechanism that was created to cause damage or other danger. Thus, the spell would sense the Alarm or Glyph of Warding spell or a mechanical pit trap, but it wouldn’t reveal a natural weakness in the floor, an unstable ceiling, or a hidden sinkhole.\n\nThis spell reveals that a trap is present but not its location. You do learn the general nature of the danger posed by a trap you sense.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.131","checked":true,"note":""},
  "flame-blade": {"time":"Bonus Action","range":"Self","components":"V, S, M (a sumac leaf)","duration":"Concentration, up to 10 minutes","desc":"You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke it again as a Bonus Action.\n\nAs a Magic action, you can make a melee spell attack with the fiery blade. On a hit, the target takes Fire damage equal to 3d6 plus your spellcasting ability modifier.\n\nThe flaming blade sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 2.","verbatim":true,"source":"SRD 5.2.1 p.132","checked":true,"note":""},
  "flaming-sphere": {"time":"Action","range":"60 feet","components":"V, S, M (a ball of wax)","duration":"Concentration, up to 1 minute","desc":"You create a 5-foot-diameter sphere of fire in an unoccupied space on the ground within range. It lasts for the duration. Any creature that ends its turn within 5 feet of the sphere makes a Dexterity saving throw, taking 2d6 Fire damage on a failed save or half as much damage on a successful one.\n\nAs a Bonus Action, you can move the sphere up to 30 feet, rolling it along the ground. If you move the sphere into a creature’s space, that creature makes the save against the sphere, and the sphere stops moving for the turn.\n\nWhen you move the sphere, you can direct it over barriers up to 5 feet tall and jump it across pits up to 10 feet wide. Flammable objects that aren’t being worn or carried start burning if touched by the sphere, and it sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 2.","verbatim":true,"source":"SRD 5.2.1 p.132","checked":true,"note":""},
  "gust-of-wind": {"time":"Action","range":"Self","components":"V, S, M (a legume seed)","duration":"Concentration, up to 1 minute","desc":"A Line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the duration. Each creature in the Line must succeed on a Strength saving throw or be pushed 15 feet away from you in a direction following the Line. A creature that ends its turn in the Line must make the same save.\n\nAny creature in the Line must spend 2 feet of movement for every 1 foot it moves when moving closer to you.\n\nThe gust disperses gas or vapor, and it extinguishes candles and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance to extinguish them.\n\nAs a Bonus Action on your later turns, you can change the direction in which the Line blasts from you.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.138","checked":true,"note":""},
  "hold-person": {"time":"Action","range":"60 feet","components":"V, S, M (a straight piece of iron)","duration":"Concentration, up to 1 minute","desc":"Choose a Humanoid that you can see within range. The target must succeed on a Wisdom saving throw or have the Paralyzed condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.","higher":"Using a Higher-Level Spell Slot. You can target one additional Humanoid for each spell slot level above 2.","verbatim":true,"source":"SRD 5.2.1 p.141","checked":true,"note":""},
  "knock": {"time":"Action","range":"60 feet","components":"V","duration":"Instantaneous","desc":"Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access.\n\nA target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked.\n\nIf the target is held shut by Arcane Lock, that spell is suppressed for 10 minutes, during which time the target can be opened and closed.\n\nWhen you cast the spell, a loud knock, audible up to 300 feet away, emanates from the target.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.143","checked":true,"note":""},
  "locate-animals-or-plants": {"time":"Action or Ritual","range":"Self","components":"V, S, M (fur from a bloodhound)","duration":"Instantaneous","desc":"Describe or name a specific kind of Beast, Plant creature, or nonmagical plant. You learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.144","checked":true,"note":""},
  "locate-object": {"time":"Action","range":"Self","components":"V, S, M (a forked twig)","duration":"Concentration, up to 10 minutes","desc":"Describe or name an object that is familiar to you. You sense the direction to the object’s location if that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement.\n\nThe spell can locate a specific object known to you if you have seen it up close—within 30 feet—at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon.\n\nThis spell can’t locate an object if any thickness of lead blocks a direct path between you and the object.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.145","checked":true,"note":""},
  "mind-spike": {"time":"Action","range":"120 feet","components":"S","duration":"Concentration, up to 1 hour","desc":"You drive a spike of psionic energy into the mind of one creature you can see within range. The target makes a Wisdom saving throw, taking 3d8 Psychic damage on a failed save or half as much damage on a successful one. On a failed save, you also always know the target’s location until the spell ends, but only while the two of you are on the same plane of existence. While you have this knowledge, the target can’t become hidden from you, and if it has the Invisible condition, it gains no benefit from that condition against you.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 2.","verbatim":true,"source":"SRD 5.2.1 p.149","checked":true,"note":""},
  "mirror-image": {"time":"Action","range":"Self","components":"V, S","duration":"1 minute","desc":"Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it’s impossible to track which image is real.\n\nEach time a creature hits you with an attack roll during the spell’s duration, roll a d6 for each of your remaining duplicates. If any of the d6s rolls a 3 or higher, one of the duplicates is hit instead of you, and the duplicate is destroyed. The duplicates otherwise ignore all other damage and effects. The spell ends when all three duplicates are destroyed.\n\nA creature is unaffected by this spell if it has the Blinded condition, Blindsight, or Truesight.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.150","checked":true,"note":""},
  "misty-step": {"time":"Bonus Action","range":"Self","components":"V","duration":"Instantaneous","desc":"Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space you can see.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.150","checked":true,"note":""},
  "nystul-s-magic-aura": {"time":"Action","range":"Touch","components":"V, S, M (a small square of silk)","duration":"24 hours","desc":"With a touch, you place an illusion on a willing creature or an object that isn’t being worn or carried. A creature gains the Mask effect below, and an object gains the False Aura effect below. The effect lasts for the duration. If you cast the spell on the same target every day for 30 days, the illusion lasts until dispelled.\n\nMask (Creature). Choose a creature type other than the target’s actual type. Spells and other magical effects treat the target as if it were a creature of the chosen type.\n\nFalse Aura (Object). You change the way the target appears to spells and magical effects that detect magical auras, such as Detect Magic. You can make a nonmagical object appear magical, make a magic item appear nonmagical, or change the object’s aura so that it appears to belong to a school of magic you choose.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.110","checked":true,"note":""},
  "pass-without-trace": {"time":"Action","range":"Self","components":"V, S, M (ashes from burned mistletoe)","duration":"Concentration, up to 1 hour","desc":"You radiate a concealing aura in a 30-foot Emanation for the duration. While in the aura, you and each creature you choose have a +10 bonus to Dexterity (Stealth) checks and leave no tracks.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.151","checked":true,"note":""},
  "phantasmal-force": {"time":"Action","range":"60 feet","components":"V, S, M (a bit of fleece)","duration":"Concentration, up to 1 minute","desc":"You attempt to craft an illusion in the mind of a creature you can see within range. The target makes an Intelligence saving throw. On a failed save, you create a phantasmal object, creature, or other phenomenon that is no larger than a 10-foot Cube and that is perceivable only to the target for the duration. The phantasm includes sound, temperature, and other stimuli.\n\nThe target can take a Study action to examine the phantasm with an Intelligence (Investigation) check against your spell save DC. If the check succeeds, the target realizes that the phantasm is an illusion, and the spell ends.\n\nWhile affected by the spell, the target treats the phantasm as if it were real and rationalizes any illogical outcomes from interacting with it. For example, if the target steps through a phantasmal bridge and survives the fall, it believes the bridge exists and something else caused it to fall.\n\nAn affected target can even take damage from the illusion if the phantasm represents a dangerous creature or hazard. On each of your turns, such a phantasm can deal 2d8 Psychic damage to the target if it is in the phantasm’s area or within 5 feet of the phantasm. The target perceives the damage as a type appropriate to the illusion.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.151","checked":true,"note":""},
  "prayer-of-healing": {"time":"10 minutes","range":"30 feet","components":"V","duration":"Instantaneous","desc":"Up to five creatures of your choice who remain within range for the spell’s entire casting gain the benefits of a Short Rest and also regain 2d8 Hit Points. A creature can’t be affected by this spell again until that creature finishes a Long Rest.","higher":"Using a Higher-Level Spell Slot. The healing increases by 1d8 for each spell slot level above 2.","verbatim":true,"source":"SRD 5.2.1 p.154","checked":true,"note":""},
  "silence": {"time":"Action or Ritual","range":"120 feet","components":"V, S","duration":"Concentration, up to 10 minutes","desc":"For the duration, no sound can be created within or pass through a 20-foot-radius Sphere centered on a point you choose within range. Any creature or object entirely inside the Sphere has Immunity to Thunder damage, and creatures have the Deafened condition while entirely inside it. Casting a spell that includes a Verbal component is impossible there.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.162","checked":true,"note":""},
  "spiritual-weapon": {"time":"Bonus Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","desc":"You create a floating, spectral force that resembles a weapon of your choice and lasts for the duration. The force appears within range in a space of your choice, and you can immediately make one melee spell attack against one creature within 5 feet of the force. On a hit, the target takes Force damage equal to 1d8 plus your spellcasting ability modifier.\n\nAs a Bonus Action on your later turns, you can move the force up to 20 feet and repeat the attack against a creature within 5 feet of it.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d8 for every slot level above 2.","verbatim":true,"source":"SRD 5.2.1 p.165","checked":true,"note":""},
  "suggestion": {"time":"Action","range":"30 feet","components":"V, M (a drop of honey)","duration":"Concentration, up to 8 hours","desc":"You suggest a course of activity—described in no more than 25 words—to one creature you can see within range that can hear and understand you. The suggestion must sound achievable and not involve anything that would obviously deal damage to the target or its allies. For example, you could say, “Fetch the key to the cult’s treasure vault, and give the key to me.” Or you could say, “Stop fighting, leave this library peacefully, and don’t return.”\n\nThe target must succeed on a Wisdom saving throw or have the Charmed condition for the duration or until you or your allies deal damage to the target. The Charmed target pursues the suggestion to the best of its ability. The suggested activity can continue for the entire duration, but if the suggested activity can be completed in a shorter time, the spell ends for the target upon completing it.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.166","checked":true,"note":""},
  "warding-bond": {"time":"Action","range":"Touch","components":"V, S, M (a pair of platinum rings worth 50+ GP each, which you and the target must wear for the duration)","duration":"1 hour","desc":"You touch another creature that is willing and create a mystic connection between you and the target until the spell ends. While the target is within 60 feet of you, it gains a +1 bonus to AC and saving throws, and it has Resistance to all damage. Also, each time it takes damage, you take the same amount of damage.\n\nThe spell ends if you drop to 0 Hit Points or if you and the target become separated by more than 60 feet. It also ends if the spell is cast again on either of the connected creatures.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.173","checked":true,"note":""},
  "zone-of-truth": {"time":"Action","range":"60 feet","components":"V, S","duration":"10 minutes","desc":"You create a magical zone that guards against deception in a 15-foot-radius Sphere centered on a point within range. Until the spell ends, a creature that enters the spell’s area for the first time on a turn or starts its turn there makes a Charisma saving throw. On a failed save, a creature can’t speak a deliberate lie while in the radius. You know whether a creature succeeds or fails on this save.\n\nAn affected creature is aware of the spell and can avoid answering questions to which it would normally respond with a lie. Such a creature can be","higher":"","verbatim":true,"source":"SRD 5.2.1 p.175","checked":true,"note":""},
  "aura-of-vitality": {"time":"Action","range":"Self","components":"V","duration":"Concentration, up to 1 minute","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:aura-of-vitality","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "beacon-of-hope": {"time":"Action","range":"30 feet","components":"V, S","duration":"Concentration, up to 1 minute","desc":"Choose any number of creatures within range. For the duration, each target has Advantage on Wisdom saving throws and Death Saving Throws and regains the maximum number of Hit Points possible from any healing.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.112","checked":true,"note":""},
  "clairvoyance": {"time":"10 minutes","range":"1 mile","components":"V, S, M (a focus worth 100+ GP, either a jeweled horn for hearing or a glass eye for seeing)","duration":"Concentration, up to 10 minutes","desc":"You create an Invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The intangible, invulnerable sensor remains in place for the duration.\n\nWhen you cast the spell, choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As a Bonus Action, you can switch between seeing and hearing.\n\nA creature that sees the sensor (such as a creature benefiting from See Invisibility or Truesight) sees a luminous orb about the size of your fist.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.115","checked":true,"note":""},
  "conjure-animals": {"time":"Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 10 minutes","desc":"You conjure nature spirits that appear as a Large pack of spectral, intangible animals in an unoccupied space you can see within range. The pack lasts for the duration, and you choose the spirits’ animal form, such as wolves, serpents, or birds.\n\nYou have Advantage on Strength saving throws while you’re within 5 feet of the pack, and when you move on your turn, you can also move the pack up to 30 feet to an unoccupied space you can see.\n\nWhenever the pack moves within 10 feet of a creature you can see and whenever a creature you can see enters a space within 10 feet of the pack or ends its turn there, you can force that creature to make a Dexterity saving throw. On a failed save, the creature takes 3d10 Slashing damage. A creature makes this save only once per turn.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 3.","verbatim":true,"source":"SRD 5.2.1 p.117","checked":true,"note":""},
  "conjure-barrage": {"time":"Action","range":"Self","components":"V, S, M (costly)","duration":"Instantaneous","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:conjure-barrage","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "counterspell": {"time":"Reaction, which you take when you see a creature within 60 feet of yourself casting a spell with Verbal, Somatic, or Material components","range":"60 feet","components":"S","duration":"Instantaneous","desc":"You attempt to interrupt a creature in the process of casting a spell. The creature makes a Constitution saving throw. On a failed save, the spell dissipates with no effect, and the action, Bonus Action, or Reaction used to cast it is wasted. If that spell was cast with a spell slot, the slot isn’t expended.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.120","checked":true,"note":""},
  "daylight": {"time":"Action","range":"60 feet","components":"V, S","duration":"1 hour","desc":"For the duration, sunlight spreads from a point within range and fills a 60-foot-radius Sphere. The sunlight’s area is Bright Light and sheds Dim Light for an additional 60 feet.\n\nAlternatively, you cast the spell on an object that isn’t being worn or carried, causing the sunlight to fill a 60-foot Emanation originating from that object. Covering that object with something opaque, such as a bowl or helm, blocks the sunlight.\n\nIf any of this spell’s area overlaps with an area of Darkness created by a spell of level 3 or lower, that other spell is dispelled.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.122","checked":true,"note":""},
  "fear": {"time":"Action","range":"Self","components":"V, S, M (a white feather)","duration":"Concentration, up to 1 minute","desc":"Each creature in a 30-foot Cone must succeed on a Wisdom saving throw or drop whatever it is holding and have the Frightened condition for the duration.\n\nA Frightened creature takes the Dash action and moves away from you by the safest route on each of its turns unless there is nowhere to move. If the creature ends its turn in a space where it doesn’t have line of sight to you, the creature makes a Wisdom saving throw. On a successful save, the spell ends on that creature.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.130","checked":true,"note":""},
  "gaseous-form": {"time":"Action","range":"Touch","components":"V, S, M (a bit of gauze)","duration":"Concentration, up to 1 hour","desc":"A willing creature you touch shape-shifts, along with everything it’s wearing and carrying, into a misty cloud for the duration. The spell ends on the target if it drops to 0 Hit Points or if it takes a Magic action to end the spell on itself.\n\nWhile in this form, the target’s only method of movement is a Fly Speed of 10 feet, and it can hover. The target can enter and occupy the space of another creature. The target has Resistance to Bludgeoning, Piercing, and Slashing damage; it has Immunity to the Prone condition; and it has Advantage on Strength, Dexterity, and Constitution saving throws. The target can pass through narrow openings, but it treats liquids as though they were solid surfaces.\n\nThe target can’t talk or manipulate objects, and any objects it was carrying or holding can’t be dropped, used, or otherwise interacted with. Finally, the target can’t attack or cast spells.","higher":"Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 3.","verbatim":true,"source":"SRD 5.2.1 p.134","checked":true,"note":""},
  "hypnotic-pattern": {"time":"Action","range":"120 feet","components":"S, M (a pinch of confetti)","duration":"Concentration, up to 1 minute","desc":"You create a twisting pattern of colors in a 30-foot Cube within range. The pattern appears for a moment and vanishes. Each creature in the area who can see the pattern must succeed on a Wisdom saving throw or have the Charmed condition for the duration. While Charmed, the creature has the Incapacitated condition and a Speed of 0.\n\nThe spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.141","checked":true,"note":""},
  "leomund-s-tiny-hut": {"time":"1 minute or Ritual","range":"Self","components":"V, S, M (a crystal bead)","duration":"8 hours","desc":"A 10-foot Emanation springs into existence around you and remains stationary for the duration. The spell fails when you cast it if the Emanation isn’t big enough to fully encapsulate all creatures in its area.\n\nCreatures and objects within the Emanation when you cast the spell can move through it freely. All other creatures and objects are barred from passing through it. Spells of level 3 or lower can’t be cast through it, and the effects of such spells can’t extend into it.\n\nThe atmosphere inside the Emanation is comfortable and dry, regardless of the weather outside. Until the spell ends, you can command the interior to have Dim Light or Darkness (no action required). The Emanation is opaque from the outside and of any color you choose, but it’s transparent from the inside.\n\nThe spell ends early if you leave the Emanation or if you cast it again.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.169","checked":true,"note":""},
  "lightning-bolt": {"time":"Action","range":"Self","components":"V, S, M (a bit of fur and a crystal rod)","duration":"Instantaneous","desc":"A stroke of lightning forming a 100-foot-long, 5-foot-wide Line blasts out from you in a direction you choose. Each creature in the Line makes a Dexterity saving throw, taking 8d6 Lightning damage on a failed save or half as much damage on a successful one.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 3.","verbatim":true,"source":"SRD 5.2.1 p.144","checked":true,"note":""},
  "magic-circle": {"time":"1 minute","range":"10 feet","components":"V, S, M (salt and powdered silver worth 100+ GP, which the spell consumes)","duration":"1 hour","desc":"You create a 10-foot-radius, 20-foot-tall Cylinder of magical energy centered on a point on the ground that you can see within range. Glowing runes appear wherever the Cylinder intersects with the floor or other surface.\n\nChoose one or more of the following types of creatures: Celestials, Elementals, Fey, Fiends, or Undead. The circle affects a creature of the chosen type in the following ways:\n\n• The creature can’t willingly enter the Cylinder by nonmagical means. If the creature tries to use teleportation or interplanar travel to do so, it must first succeed on a Charisma saving throw.\n• The creature has Disadvantage on attack rolls against targets within the Cylinder.\n• Targets within the Cylinder can’t be possessed by or gain the Charmed or Frightened condition from the creature.\n\nEach time you cast this spell, you can cause its magic to operate in the reverse direction, preventing a creature of the specified type from leaving the Cylinder and protecting targets outside it.","higher":"Using a Higher-Level Spell Slot. The duration increases by 1 hour for each spell slot level above 3.","verbatim":true,"source":"SRD 5.2.1 p.145","checked":true,"note":""},
  "major-image": {"time":"Action","range":"120 feet","components":"V, S, M (a bit of fleece)","duration":"Concentration, up to 10 minutes","desc":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot Cube. The image appears at a spot that you can see within range and lasts for the duration. It seems real, including sounds, smells, and temperature appropriate to the thing depicted, but it can’t deal damage or cause conditions.\n\nIf you are within range of the illusion, you can take a Magic action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example.\n\nPhysical interaction with the image reveals it to be an illusion, for things can pass through it. A creature that takes a Study action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature.","higher":"Using a Higher-Level Spell Slot. The spell lasts until dispelled, without requiring Concentration, if cast with a level 4+ spell slot.","verbatim":true,"source":"SRD 5.2.1 p.147","checked":true,"note":""},
  "mass-healing-word": {"time":"Bonus Action","range":"60 feet","components":"V","duration":"Instantaneous","desc":"Up to six creatures of your choice that you can see within range regain Hit Points equal to 2d4 plus your spellcasting ability modifier.","higher":"Using a Higher-Level Spell Slot. The healing increases by 1d4 for each spell slot level above 3.","verbatim":true,"source":"SRD 5.2.1 p.148","checked":true,"note":""},
  "nondetection": {"time":"Action","range":"Touch","components":"V, S, M (a pinch of diamond dust worth 25+ GP, which the spell consumes)","duration":"8 hours","desc":"For the duration, you hide a target that you touch from Divination spells. The target can be a willing creature, or it can be a place or an object no larger than 10 feet in any dimension. The target can’t be targeted by any Divination spell or perceived through magical scrying sensors.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.151","checked":true,"note":""},
  "phantom-steed": {"time":"1 minute or Ritual","range":"30 feet","components":"V, S","duration":"1 hour","desc":"A Large, quasi-real, horselike creature appears on the ground in an unoccupied space of your choice within range. You decide the creature’s appearance, and it is equipped with a saddle, bit, and bridle. Any of the equipment created by the spell vanishes in a puff of smoke if it is carried more than 10 feet away from the steed.\n\nFor the duration, you or a creature you choose can ride the steed. The steed uses the Riding Horse stat block (see “Monsters”), except it has a Speed of 100 feet and can travel 13 miles in an hour. When the spell ends, the steed gradually fades, giving the rider 1 minute to dismount. The spell ends early if the steed takes any damage.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.152","checked":true,"note":""},
  "sending": {"time":"Action","range":"Unlimited","components":"V, S, M (a copper wire)","duration":"Instantaneous","desc":"You send a short message of 25 words or fewer to a creature you have met or a creature described to you by someone who has met it. The target hears the message in its mind, recognizes you as the sender if it knows you, and can answer in a like manner immediately. The spell enables targets to understand the meaning of your message.\n\nYou can send the message across any distance and even to other planes of existence, but if the target is on a different plane than you, there is a 5 percent chance that the message doesn’t arrive. You know if the delivery fails.\n\nUpon receiving your message, a creature can block your ability to reach it again with this spell for 8 hours. If you try to send another message during that time, you learn that you are blocked, and the spell fails.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.161","checked":true,"note":""},
  "sleet-storm": {"time":"Action","range":"150 feet","components":"V, S, M (a miniature umbrella)","duration":"Concentration, up to 1 minute","desc":"Until the spell ends, sleet falls in a 40-foot-tall, 20-foot-radius Cylinder centered on a point you choose within range. The area is Heavily Obscured, and exposed flames in the area are doused.\n\nGround in the Cylinder is Difficult Terrain. When a creature enters the Cylinder for the first time on a turn or starts its turn there, it must succeed on a Dexterity saving throw or have the Prone condition and lose Concentration.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.163","checked":true,"note":""},
  "slow": {"time":"Action","range":"120 feet","components":"V, S, M (a drop of molasses)","duration":"Concentration, up to 1 minute","desc":"You alter time around up to six creatures of your choice in a 40-foot Cube within range. Each target must succeed on a Wisdom saving throw or be affected by this spell for the duration.\n\nAn affected target’s Speed is halved, it takes a −2 penalty to AC and Dexterity saving throws, and it can’t take Reactions. On its turns, it can take either an action or a Bonus Action, not both, and it can make only one attack if it takes the Attack action. If it casts a spell with a Somatic component, there is a 25 percent chance the spell fails as a result of the target making the spell’s gestures too slowly.\n\nAn affected target repeats the save at the end of each of its turns, ending the spell on itself on a success.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.163","checked":true,"note":""},
  "speak-with-plants": {"time":"Action","range":"Self","components":"V, S","duration":"10 minutes","desc":"You imbue plants in an immobile 30-foot Emanation with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell’s area within the past day, gaining information about creatures that have passed, weather, and other circumstances.\n\nYou can also turn Difficult Terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into Difficult Terrain that lasts for the duration.\n\nThe spell doesn’t enable plants to uproot themselves and move about, but they can move their branches, tendrils, and stalks for you.\n\nIf a Plant creature is in the area, you can communicate with it as if you shared a common language.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.164","checked":true,"note":""},
  "stinking-cloud": {"time":"Action","range":"90 feet","components":"V, S, M (a rotten egg)","duration":"Concentration, up to 1 minute","desc":"You create a 20-foot-radius Sphere of yellow, nauseating gas centered on a point within range. The cloud is Heavily Obscured. The cloud lingers in the air for the duration or until a strong wind (such as the one created by Gust of Wind) disperses it.\n\nEach creature that starts its turn in the Sphere must succeed on a Constitution saving throw or have the Poisoned condition until the end of the current turn. While Poisoned in this way, the creature can’t take an action or a Bonus Action.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.165","checked":true,"note":""},
  "tongues": {"time":"Action","range":"Touch","components":"V, M (a miniature ziggurat)","duration":"1 hour","desc":"This spell grants the creature you touch the ability to understand any spoken or signed language that it hears or sees. Moreover, when the target communicates by speaking or signing, any creature that knows at least one language can understand it if that creature can hear the speech or see the signing.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.169","checked":true,"note":""},
  "vampiric-touch": {"time":"Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 minute","desc":"The touch of your shadow-wreathed hand can siphon life force from others to heal your wounds. Make a melee spell attack against one creature within reach. On a hit, the target takes 3d6 Necrotic damage, and you regain Hit Points equal to half the amount of Necrotic damage dealt.\n\nUntil the spell ends, you can make the attack again on each of your turns as a Magic action, targeting the same creature or a different one.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 3.","verbatim":true,"source":"SRD 5.2.1 p.171","checked":true,"note":""},
  "aura-of-life": {"time":"Action","range":"Self","components":"V","duration":"Concentration, up to 10 minutes","desc":"An aura radiates from you in a 30-foot Emanation for the duration. While in the aura, you and your allies have Resistance to Necrotic damage, and your Hit Point maximums can’t be reduced. If an ally with 0 Hit Points starts its turn in the aura, that ally regains 1 Hit Point.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.111","checked":true,"note":""},
  "aura-of-purity": {"time":"Action","range":"Self","components":"V","duration":"Concentration, up to 10 minutes","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:aura-of-purity","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "banishment": {"time":"Action","range":"30 feet","components":"V, S, M (a pentacle)","duration":"Concentration, up to 1 minute","desc":"One creature that you can see within range must succeed on a Charisma saving throw or be transported to a harmless demiplane for the duration. While there, the target has the Incapacitated condition. When the spell ends, the target reappears in the space it left or in the nearest unoccupied space if that space is occupied.\n\nIf the target is an Aberration, a Celestial, an Elemental, a Fey, or a Fiend, the target doesn’t return if the spell lasts for 1 minute. The target is instead transported to a random location on a plane (GM’s choice) associated with its creature type.","higher":"Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 4.","verbatim":true,"source":"SRD 5.2.1 p.112","checked":true,"note":""},
  "blight": {"time":"Action","range":"30 feet","components":"V, S","duration":"Instantaneous","desc":"A creature that you can see within range makes a Constitution saving throw, taking 8d8 Necrotic damage on a failed save or half as much damage on a successful one. A Plant creature automatically fails the save.\n\nAlternatively, target a nonmagical plant that isn’t a creature, such as a tree or shrub. It doesn’t make a save; it simply withers and dies.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 4.","verbatim":true,"source":"SRD 5.2.1 p.113","checked":true,"note":""},
  "charm-monster": {"time":"Action","range":"30 feet","components":"V, S","duration":"1 hour","desc":"One creature you can see within range makes a Wisdom saving throw. It does so with Advantage if you or your allies are fighting it. On a failed save, the target has the Charmed condition until the spell ends or until you or your allies damage it. The Charmed creature is Friendly to you. When the spell ends, the target knows it was Charmed by you.","higher":"Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 4.","verbatim":true,"source":"SRD 5.2.1 p.114","checked":true,"note":""},
  "confusion": {"time":"Action","range":"90 feet","components":"V, S, M (three nut shells)","duration":"Concentration, up to 1 minute","desc":"Each creature in a 10-foot-radius Sphere centered on a point you choose within range must succeed on a Wisdom saving throw, or that target can’t take Bonus Actions or Reactions and must roll 1d10 at the start of each of its turns to determine its behavior for that turn, consulting the table below.\n\n1d10 | Behavior for the Turn\n1 | The target doesn’t take an action, and it uses all\nits movement to move. Roll 1d4 for the direc-\ntion: 1, north; 2, east; 3, south; or 4, west.\n2–6 | The target doesn’t move or take actions.\n7–8 | The target doesn’t move, and it takes the At-\ntack action to make one melee attack against\na random creature within reach. If none are\nwithin reach, the target takes no action.\n9–10 | The target chooses its behavior.\n\nAt the end of each of its turns, an affected target repeats the save, ending the spell on itself on a success.","higher":"Using a Higher-Level Spell Slot. The Sphere’s radius increases by 5 feet for each spell slot level above 4.","verbatim":true,"source":"SRD 5.2.1 p.117","checked":true,"note":""},
  "conjure-minor-elementals": {"time":"Action","range":"Self","components":"V, S","duration":"Concentration, up to 10 minutes","desc":"You conjure spirits from the Elemental Planes that flit around you in a 15-foot Emanation for the duration. Until the spell ends, any attack you make deals an extra 2d8 damage when you hit a creature in the Emanation. This damage is Acid, Cold, Fire, or Lightning (your choice when you make the attack).\n\nIn addition, the ground in the Emanation is Difficult Terrain for your enemies.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 4.","verbatim":true,"source":"SRD 5.2.1 p.118","checked":true,"note":""},
  "control-water": {"time":"Action","range":"300 feet","components":"V, S, M (a mixture of water and dust)","duration":"Concentration, up to 10 minutes","desc":"Until the spell ends, you control any water inside an area you choose that is a Cube up to 100 feet on a side, using one of the following effects. As a Magic action on your later turns, you can repeat the same effect or choose a different one.\n\nFlood. You cause the water level of all standing water in the area to rise by as much as 20 feet. If you choose an area in a large body of water, you instead create a 20-foot tall wave that travels from one side of the area to the other and then crashes. Any Huge or smaller vehicles in the wave’s path are carried with it to the other side. Any Huge or smaller vehicles struck by the wave have a 25 percent chance of capsizing.\n\nThe water level remains elevated until the spell ends or you choose a different effect. If this effect produced a wave, the wave repeats on the start of your next turn while the flood effect lasts.\n\nPart Water. You part water in the area and create a trench. The trench extends across the spell’s area, and the separated water forms a wall to either side. The trench remains until the spell ends or you choose a different effect. The water then slowly fills in the trench over the course of the next round until the normal water level is restored.\n\nRedirect Flow. You cause flowing water in the area to move in a direction you choose, even if the water has to flow over obstacles, up walls, or in other unlikely directions. The water in the area moves as you direct it, but once it moves beyond the spell’s area, it resumes its flow based on the terrain. The water continues to move in the direction you chose until the spell ends or you choose a different effect.\n\nWhirlpool. You cause a whirlpool to form in the center of the area, which must be at least 50 feet square and 25 feet deep. The whirlpool lasts until you choose a different effect or the spell ends. The whirlpool is 5 feet wide at the base, up to 50 feet wide at the top, and 25 feet tall. Any creature in the water and within 25 feet of the whirlpool is pulled 10 feet toward it. When a creature enters the whirlpool for the first time on a turn or ends its turn there, it makes a Strength saving throw. On a failed save, the creature takes 2d8 Bludgeoning damage. On a successful save, the creature takes half as much damage. A creature can swim away from the whirlpool only if it first takes an action to pull away and succeeds on a Strength (Athletics) check against your spell save DC.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.119","checked":true,"note":""},
  "death-ward": {"time":"Action","range":"Touch","components":"V, S","duration":"8 hours","desc":"You touch a creature and grant it a measure of protection from death. The first time the target would drop to 0 Hit Points before the spell ends, the target instead drops to 1 Hit Point, and the spell ends.\n\nIf the spell is still in effect when the target is subjected to an effect that would kill it instantly without dealing damage, that effect is negated against the target, and the spell ends.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.122","checked":true,"note":""},
  "dimension-door": {"time":"Action","range":"500 feet","components":"V","duration":"Instantaneous","desc":"You teleport to a location within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as “200 feet straight downward” or “300 feet upward to the northwest at a 45-degree angle.”\n\nYou can also teleport one willing creature. The creature must be within 5 feet of you when you teleport, and it teleports to a space within 5 feet of your destination space.\n\nIf you, the other creature, or both would arrive in a space occupied by a creature or completely filled by one or more objects, you and any creature traveling with you each take 4d6 Force damage, and the teleportation fails.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.123","checked":true,"note":""},
  "divination": {"time":"Action or Ritual","range":"Self","components":"V, S, M (incense worth 25+ GP, which the spell consumes)","duration":"Instantaneous","desc":"This spell puts you in contact with a god or a god’s servants. You ask one question about a specific goal, event, or activity to occur within 7 days. The GM offers a truthful reply, which might be a short phrase or cryptic rhyme. The spell doesn’t account for circumstances that might change the answer, such as the casting of other spells.\n\nIf you cast the spell more than once before finishing a Long Rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.125","checked":true,"note":""},
  "dominate-beast": {"time":"Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","desc":"One Beast you can see within range must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The target has Advantage on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success.\n\nYou have a telepathic link with the Charmed target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as “Attack that creature,” “Move over there,” or “Fetch that object.” The target does its best to obey on its turn. If it completes an order and doesn’t receive further direction from you, it acts and moves as it likes, focusing on protecting itself.\n\nYou can command the target to take a Reaction but must take your own Reaction to do so.","higher":"Using a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 5 (up to 10 minutes), 6 (up to 1 hour), or 7+ (up to 8 hours).","verbatim":true,"source":"SRD 5.2.1 p.125","checked":true,"note":""},
  "fire-shield": {"time":"Action","range":"Self","components":"V, S, M (a bit of phosphorus or a firefly)","duration":"10 minutes","desc":"Wispy flames wreathe your body for the duration, shedding Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.\n\nThe flames provide you with a warm shield or a chill shield, as you choose. The warm shield grants you Resistance to Cold damage, and the chill shield grants you Resistance to Fire damage.\n\nIn addition, whenever a creature within 5 feet of you hits you with a melee attack roll, the shield erupts with flame. The attacker takes 2d8 Fire damage from a warm shield or 2d8 Cold damage from a chill shield.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.132","checked":true,"note":""},
  "greater-invisibility": {"time":"Action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 minute","desc":"A creature you touch has the Invisible condition until the spell ends.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.137","checked":true,"note":""},
  "guardian-of-faith": {"time":"Action","range":"30 feet","components":"V","duration":"8 hours","desc":"A Large spectral guardian appears and hovers for the duration in an unoccupied space that you can see within range. The guardian occupies that space and is invulnerable, and it appears in a form appropriate for your deity or pantheon.\n\nAny enemy that moves to a space within 10 feet of the guardian for the first time on a turn or starts its turn there makes a Dexterity saving throw, taking 20 Radiant damage on a failed save or half as much damage on a successful one. The guardian vanishes when it has dealt a total of 60 damage.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.137","checked":true,"note":""},
  "hallucinatory-terrain": {"time":"10 minutes","range":"300 feet","components":"V, S, M (a mushroom)","duration":"24 hours","desc":"You make natural terrain in a 150-foot Cube in range look, sound, and smell like another sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road. Manufactured structures, equipment, and creatures within the area aren’t changed.\n\nThe tactile characteristics of the terrain are unchanged, so creatures entering the area are likely to notice the illusion. If the difference isn’t obvious by touch, a creature examining the illusion can take the Study action to make an Intelligence (Investigation) check against your spell save DC to disbelieve it. If a creature discerns that the terrain is illusory, the creature sees a vague image superimposed on the real terrain.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.139","checked":true,"note":""},
  "locate-creature": {"time":"Action","range":"Self","components":"V, S, M (fur from a bloodhound)","duration":"Concentration, up to 1 hour","desc":"Describe or name a creature that is familiar to you. You sense the direction to the creature’s location if that creature is within 1,000 feet of you. If the creature is moving, you know the direction of its movement.\n\nThe spell can locate a specific creature known to you or the nearest creature of a specific kind (such as a human or a unicorn) if you have seen such a creature up close—within 30 feet—at least once. If the creature you described or named is in a different form, such as under the effects of a Flesh to Stone or Polymorph spell, this spell doesn’t locate the creature.\n\nThis spell can’t locate a creature if any thickness of lead blocks a direct path between you and the creature.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.145","checked":true,"note":""},
  "polymorph": {"time":"Action","range":"60 feet","components":"V, S, M (a caterpillar cocoon)","duration":"Concentration, up to 1 hour","desc":"You attempt to transform a creature that you can see within range into a Beast. The target must succeed on a Wisdom saving throw or shape-shift into a Beast form for the duration. That form can be any Beast you choose that has a Challenge Rating equal to or less than the target’s (or the target’s level if it doesn’t have a Challenge Rating). The target’s game statistics are replaced by the stat block of the chosen Beast, but the target retains its alignment, personality, creature type, Hit Points, and Hit Point Dice. See the “Animals” section of “Monsters” for a sample of Beast stat blocks.\n\nThe target gains a number of Temporary Hit Points equal to the Hit Points of the Beast form. These Temporary Hit Points vanish if any remain when the spell ends. The spell ends early on the target if it has no Temporary Hit Points left.\n\nThe target is limited in the actions it can perform by the anatomy of its new form, and it can’t speak or cast spells.\n\nThe target’s gear melds into the new form. The creature can’t use or otherwise benefit from any of that equipment.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.153","checked":true,"note":""},
  "vitriolic-sphere": {"time":"Action","range":"150 feet","components":"V, S, M (a drop of bile)","duration":"Instantaneous","desc":"You point at a location within range, and a glowing, 1-foot-diameter ball of acid streaks there and explodes in a 20-foot-radius Sphere. Each creature in that area makes a Dexterity saving throw. On a failed save, a creature takes 10d4 Acid damage and another 5d4 Acid damage at the end of its next turn. On a successful save, a creature takes half the initial damage only.","higher":"Using a Higher-Level Spell Slot. The initial damage increases by 2d4 for each spell slot level above 4.","verbatim":true,"source":"SRD 5.2.1 p.172","checked":true,"note":""},
  "antilife-shell": {"time":"Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 hour","desc":"An aura extends from you in a 10-foot Emanation for the duration. The aura prevents creatures other than Constructs and Undead from passing or reaching through it. An affected creature can cast spells or make attacks with Ranged or Reach weapons through the barrier.\n\nIf you move so that an affected creature is forced to pass through the barrier, the spell ends.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.109","checked":true,"note":""},
  "awaken": {"time":"8 hours","range":"Touch","components":"V, S, M (an agate worth 1,000+ GP, which the spell consumes)","duration":"Instantaneous","desc":"You spend the casting time tracing magical pathways within a precious gemstone, and then touch the target. The target must be either a Beast or Plant creature with an Intelligence of 3 or less or a natural plant that isn’t a creature. The target gains an Intelligence of 10 and the ability to speak one language you know. If the target is a natural plant, it becomes a Plant creature and gains the ability to move its limbs, roots, vines, creepers, and so forth, and it gains senses similar to a human’s. The GM chooses statistics appropriate for the awakened Plant, such as the statistics for the Awakened\n\nShrub or Awakened Tree in “Monsters.” The awakened target has the Charmed condition\n\nfor 30 days or until you or your allies deal damage to it. When that condition ends, the awakened creature chooses its attitude toward you.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.111","checked":true,"note":""},
  "cloudkill": {"time":"Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 10 minutes","desc":"You create a 20-foot-radius Sphere of yellow-green fog centered on a point within range. The fog lasts for the duration or until strong wind (such as the one created by Gust of Wind) disperses it, ending the spell. Its area is Heavily Obscured.\n\nEach creature in the Sphere makes a Constitution saving throw, taking 5d8 Poison damage on a failed save or half as much damage on a successful one. A creature must also make this save when the Sphere moves into its space and when it enters the Sphere or ends its turn there. A creature makes this save only once per turn.\n\nThe Sphere moves 10 feet away from you at the start of each of your turns.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 5.","verbatim":true,"source":"SRD 5.2.1 p.116","checked":true,"note":""},
  "commune-with-nature": {"time":"1 minute or Ritual","range":"Self","components":"V, S","duration":"Instantaneous","desc":"You commune with nature spirits and gain knowledge of the surrounding area. In the outdoors, the spell gives you knowledge of the area within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 feet. The spell doesn’t function where nature has been replaced by construction, such as in castles and settlements.\n\nChoose three of the following facts; you learn those facts as they pertain to the spell’s area:\n\n• Locations of settlements\n• Locations of portals to other planes of existence\n• Location of one Challenge Rating 10+ creature (GM’s choice) that is a Celestial, an Elemental, a Fey, a Fiend, or an Undead\n• The most prevalent kind of plant, mineral, or Beast (you choose which to learn)\n• Locations of bodies of water\n\nFor example, you could determine the location of a powerful monster in the area, the locations of bodies of water, and the locations of any towns.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.116","checked":true,"note":""},
  "conjure-elemental": {"time":"Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 10 minutes","desc":"You conjure a Large, intangible spirit from the Elemental Planes that appears in an unoccupied space within range. Choose the spirit’s element, which determines its damage type: air (Lightning), earth (Thunder), fire (Fire), or water (Cold). The spirit lasts for the duration.\n\nWhenever a creature you can see enters the spirit’s space or starts its turn within 5 feet of the spirit, you can force that creature to make a Dexterity saving throw if the spirit has no creature Restrained. On failed save, the target takes 8d8 damage of the spirit’s type, and the target has the Restrained condition until the spell ends. At the start of each of its turns, the Restrained target repeats the save. On a failed save, the target takes 4d8 damage of the spirit’s type. On a successful save, the target isn’t Restrained by the spirit.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 5.","verbatim":true,"source":"SRD 5.2.1 p.118","checked":true,"note":""},
  "dominate-person": {"time":"Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","desc":"One Humanoid you can see within range must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The target has Advantage on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success.\n\nYou have a telepathic link with the Charmed target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as “Attack that creature,” “Move over there,” or “Fetch that object.” The target does its best to obey on its turn. If it completes an order and doesn’t receive further direction from you, it acts and moves as it likes, focusing on protecting itself.\n\nYou can command the target to take a Reaction but must take your own Reaction to do so.","higher":"Using a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 6 (up to 10 minutes), 7 (up to 1 hour), or 8+ (up to 8 hours).","verbatim":true,"source":"SRD 5.2.1 p.126","checked":true,"note":""},
  "dream": {"time":"1 minute","range":"Special","components":"V, S, M (a handful of sand)","duration":"8 hours","desc":"You target a creature you know on the same plane of existence. You or a willing creature you touch enters a trance state to act as a dream messenger. While in the trance, the messenger is Incapacitated and has a Speed of 0.\n\nIf the target is asleep, the messenger appears in the target’s dreams and can converse with the target as long as it remains asleep, through the spell’s duration. The messenger can also shape the dream’s environment, creating landscapes, objects, and other images. The messenger can emerge from the trance at any time, ending the spell. The target recalls the dream perfectly upon waking.\n\nIf the target is awake when you cast the spell, the messenger knows it and can either end the trance (and the spell) or wait for the target to sleep, at which point the messenger enters its dreams.\n\nYou can make the messenger terrifying to the target. If you do so, the messenger can deliver a message of no more than ten words, and then the target makes a Wisdom saving throw. On a failed save, the target gains no benefit from its rest, and it takes 3d6 Psychic damage when it wakes up.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.126","checked":true,"note":""},
  "hallow": {"time":"24 hours","range":"Touch","components":"V, S, M (incense worth 1,000+ GP, which the spell consumes)","duration":"Until dispelled","desc":"You touch a point and infuse an area around it with holy or unholy power. The area can have a radius up to 60 feet, and the spell fails if the radius includes an area already under the effect of Hallow. The affected area has the following effects.\n\nHallowed Ward. Choose any of these creature types: Aberration, Celestial, Elemental, Fey, Fiend, or Undead. Creatures of the chosen types can’t willingly enter the area, and any creature that is possessed by or that has the Charmed or Frightened condition from such creatures isn’t possessed, Charmed, or Frightened by them while in the area.\n\nExtra Effect. You bind an extra effect to the area from the list below:\n\nCourage. Creatures of any types you choose can’t gain the Frightened condition while in the area.\n\nDarkness. Darkness fills the area. Normal light, as well as magical light created by spells of a level lower than this spell, can’t illuminate the area.\n\nDaylight. Bright light fills the area. Magical Darkness created by spells of a level lower than this spell can’t extinguish the light.\n\nPeaceful Rest. Dead bodies interred in the area can’t be turned into Undead.\n\nExtradimensional Interference. Creatures of any types you choose can’t enter or exit the area using teleportation or interplanar travel.\n\nFear. Creatures of any types you choose have the Frightened condition while in the area.\n\nResistance. Creatures of any types you choose have Resistance to one damage type of your choice while in the area.\n\nSilence. No sound can emanate from within the area, and no sound can reach into it.\n\nTongues. Creatures of any types you choose can communicate with any other creature in the area even if they don’t share a common language.\n\nVulnerability. Creatures of any types you choose have Vulnerability to one damage type of your choice while in the area.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.138","checked":true,"note":""},
  "hold-monster": {"time":"Action","range":"90 feet","components":"V, S, M (a straight piece of iron)","duration":"Concentration, up to 1 minute","desc":"Choose a creature that you can see within range. The target must succeed on a Wisdom saving throw or have the Paralyzed condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.","higher":"Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 5.","verbatim":true,"source":"SRD 5.2.1 p.140","checked":true,"note":""},
  "insect-plague": {"time":"Action","range":"300 feet","components":"V, S, M (a locust)","duration":"Concentration, up to 10 minutes","desc":"Swarming locusts fill a 20-foot-radius Sphere centered on a point you choose within range. The Sphere remains for the duration, and its area is Lightly Obscured and Difficult Terrain.\n\nWhen the swarm appears, each creature in it makes a Constitution saving throw, taking 4d10 Piercing damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell’s area for the first time on a turn or ends its turn there. A creature makes this save only once per turn.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 5.","verbatim":true,"source":"SRD 5.2.1 p.143","checked":true,"note":""},
  "legend-lore": {"time":"10 minutes","range":"Self","components":"V, S, M (incense worth 250+ GP, which the spell consumes, and four ivory strips worth 50+ GP each)","duration":"Instantaneous","desc":"Name or describe a famous person, place, or object. The spell brings to your mind a brief summary of the significant lore about that famous thing, as described by the GM.\n\nThe lore might consist of important details, amusing revelations, or even secret lore that has never been widely known. The more information you already know about the thing, the more precise and detailed the information you receive is. That information is accurate but might be couched in figurative language or poetry, as determined by the GM.\n\nIf the famous thing you chose isn’t actually famous, you hear sad musical notes played on a trombone, and the spell fails.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.144","checked":true,"note":""},
  "mislead": {"time":"Action","range":"Self","components":"S","duration":"Concentration, up to 1 hour","desc":"You gain the Invisible condition at the same time that an illusory double of you appears where you are standing. The double lasts for the duration, but the invisibility ends immediately after you make an attack roll, deal damage, or cast a spell.\n\nAs a Magic action, you can move the illusory double up to twice your Speed and make it gesture, speak, and behave in whatever way you choose. It is intangible and invulnerable.\n\nYou can see through its eyes and hear through its ears as if you were located where it is.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.150","checked":true,"note":""},
  "seeming": {"time":"Action","range":"30 feet","components":"V, S","duration":"8 hours","desc":"You give an illusory appearance to each creature of your choice that you can see within range. An unwilling target can make a Charisma saving throw, and if it succeeds, it is unaffected by this spell.\n\nYou can give the same appearance or different ones to the targets. The spell can change the appearance of the targets’ bodies and equipment. You can make each creature seem 1 foot shorter or taller and appear heavier or lighter. A target’s new appearance must have the same basic arrangement of limbs as the target, but the extent of the illusion is otherwise up to you. The spell lasts for the duration.\n\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to a creature’s outfit, objects pass through the hat.\n\nA creature that takes the Study action to examine a target can make an Intelligence (Investigation) check against your spell save DC. If it succeeds, it becomes aware that the target is disguised.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.160","checked":true,"note":""},
  "synaptic-static": {"time":"Action","range":"120 feet","components":"V, S","duration":"Instantaneous","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:synaptic-static","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "telekinesis": {"time":"Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 10 minutes","desc":"You gain the ability to move or manipulate creatures or objects by thought. When you cast the spell and as a Magic action on your later turns before the spell ends, you can exert your will on one creature or object that you can see within range, causing the appropriate effect below. You can affect the same target round after round or choose a new one at any time. If you switch targets, the prior target is no longer affected by the spell.\n\nCreature. You can try to move a Huge or smaller creature. The target must succeed on a Strength saving throw, or you move it up to 30 feet in any direction within the spell’s range. Until the end of your next turn, the creature has the Restrained condition, and if you lift it into the air, it is suspended there. It falls at the end of your next turn unless you use this option on it again and it fails the save.\n\nObject. You can try to move a Huge or smaller object. If the object isn’t being worn or carried, you automatically move it up to 30 feet in any direction within the spell’s range.\n\nIf the object is worn or carried by a creature, that creature must succeed on a Strength saving throw, or you pull the object away and move it up to 30 feet in any direction within the spell’s range.\n\nYou can exert fine control on objects with your telekinetic grip, such as manipulating a simple tool,","higher":"","verbatim":true,"source":"SRD 5.2.1 p.167","checked":true,"note":""},
  "teleportation-circle": {"time":"1 minute","range":"10 feet","components":"V, M (rare inks worth 50+ GP, which the spell consumes)","duration":"1 round","desc":"As you cast the spell, you draw a 5-foot-radius circle on the ground inscribed with sigils that link your location to a permanent teleportation circle of your choice whose sigil sequence you know and that is on the same plane of existence as you. A shimmering portal opens within the circle you drew and remains open until the end of your next turn. Any creature that enters the portal instantly appears within 5 feet of the destination circle or in the nearest unoccupied space if that space is occupied.\n\nMany major temples, guildhalls, and other important places have permanent teleportation circles. Each circle includes a unique sigil sequence—a string of runes arranged in a particular pattern.\n\nWhen you first gain the ability to cast this spell, you learn the sigil sequences for two destinations on the Material Plane, determined by the GM. You might learn additional sigil sequences during your adventures. You can commit a new sigil sequence to memory after studying it for 1 minute.\n\nYou can create a permanent teleportation circle by casting this spell in the same location every day for 365 days.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.168","checked":true,"note":""},
  "arcane-gate": {"time":"Action","range":"500 feet","components":"V, S","duration":"Concentration, up to 10 minutes","desc":"","higher":"","verbatim":false,"source":"https://dnd2024.wikidot.com/spell:arcane-gate","checked":false,"note":"Community data (casting time, range, components and duration from a wiki table; unverified). No description is stored: open the Source link."},
  "chain-lightning": {"time":"Action","range":"150 feet","components":"V, S, M (three silver pins)","duration":"Instantaneous","desc":"You launch a lightning bolt toward a target you can see within range. Three bolts then leap from that target to as many as three other targets of your choice, each of which must be within 30 feet of the first target. A target can be a creature or an object and can be targeted by only one of the bolts.\n\nEach target makes a Dexterity saving throw, taking 10d8 Lightning damage on a failed save or half as much damage on a successful one.","higher":"Using a Higher-Level Spell Slot. One additional bolt leaps from the first target to another target for each spell slot level above 6.","verbatim":true,"source":"SRD 5.2.1 p.114","checked":true,"note":""},
  "circle-of-death": {"time":"Action","range":"150 feet","components":"V, S, M (the powder of a crushed black pearl worth 500+ GP)","duration":"Instantaneous","desc":"Negative energy ripples out in a 60-foot-radius Sphere from a point you choose within range. Each creature in that area makes a Constitution saving throw, taking 8d8 Necrotic damage on a failed save or half as much damage on a successful one.","higher":"Using a Higher-Level Spell Slot. The damage increases by 2d8 for each spell slot level above 6.","verbatim":true,"source":"SRD 5.2.1 p.115","checked":true,"note":""},
  "disintegrate": {"time":"Action","range":"60 feet","components":"V, S, M (a lodestone and dust)","duration":"Instantaneous","desc":"You launch a green ray at a target you can see within range. The target can be a creature, a nonmagical object, or a creation of magical force, such as the wall created by Wall of Force.\n\nA creature targeted by this spell makes a Dexterity saving throw. On a failed save, the target takes 10d6 + 40 Force damage. If this damage reduces it to 0 Hit Points, it and everything nonmagical it is wearing and carrying are disintegrated into gray dust. The target can be revived only by a True Resurrection or a Wish spell.\n\nThis spell automatically disintegrates a Large or smaller nonmagical object or a creation of magical force. If such a target is Huge or larger, this spell disintegrates a 10-foot-Cube portion of it.","higher":"Using a Higher-Level Spell Slot. The damage increases by 3d6 for each spell slot level above 6.","verbatim":true,"source":"SRD 5.2.1 p.124","checked":true,"note":""},
  "eyebite": {"time":"Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 minute","desc":"For the duration, your eyes become an inky void. One creature of your choice within 60 feet of you that you can see must succeed on a Wisdom saving throw or be affected by one of the following effects of your choice for the duration.\n\nOn each of your turns until the spell ends, you can take a Magic action to target another creature but can’t target a creature again if it has succeeded on a save against this casting of the spell.\n\nAsleep. The target has the Unconscious condition. It wakes up if it takes any damage or if another creature takes an action to shake it awake.\n\nPanicked. The target has the Frightened condition. On each of its turns, the Frightened target must take the Dash action and move away from you by the safest and shortest route available. If the target moves to a space at least 60 feet away from you where it can’t see you, this effect ends.\n\nSickened. The target has the Poisoned condition.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.129","checked":true,"note":""},
  "flesh-to-stone": {"time":"Action","range":"60 feet","components":"V, S, M (a cockatrice feather)","duration":"Concentration, up to 1 minute","desc":"You attempt to turn one creature that you can see within range into stone. The target makes a Constitution saving throw. On a failed save, it has the Restrained condition for the duration. On a successful save, its Speed is 0 until the start of your next turn. Constructs automatically succeed on the save.\n\nA Restrained target makes another Constitution saving throw at the end of each of its turns. If it successfully saves against this spell three times, the spell ends. If it fails its saves three times, it is turned to stone and has the Petrified condition for the duration. The successes and failures needn’t be consecutive; keep track of both until the target collects three of a kind.\n\nIf you maintain your Concentration on this spell for the entire possible duration, the target is Petrified until the condition is ended by Greater Restoration or similar magic.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.133","checked":true,"note":""},
  "globe-of-invulnerability": {"time":"Action","range":"Self","components":"V, S, M (a glass bead)","duration":"Concentration, up to 1 minute","desc":"An immobile, shimmering barrier appears in a 10-foot Emanation around you and remains for the duration.\n\nAny spell of level 5 or lower cast from outside the barrier can’t affect anything within it. Such a spell can target creatures and objects within the barrier, but the spell has no effect on them. Similarly, the area within the barrier is excluded from areas of effect created by such spells.","higher":"Using a Higher-Level Spell Slot. The barrier blocks spells of 1 level higher for each spell slot level above 6.","verbatim":true,"source":"SRD 5.2.1 p.136","checked":true,"note":""},
  "heroes-feast": {"time":"10 minutes","range":"Self","components":"V, S, M (a gem-encrusted bowl worth 1,000+ GP, which the spell consumes)","duration":"Instantaneous","desc":"You conjure a feast that appears on a surface in an unoccupied 10-foot Cube next to you. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don’t set in until this hour is over. Up to twelve creatures can partake of the feast.\n\nA creature that partakes gains several benefits, which last for 24 hours. The creature has Resistance to Poison damage, and it has Immunity to the Frightened and Poisoned conditions. Its Hit Point maximum also increases by 2d10, and it gains the same number of Hit Points.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.140","checked":true,"note":""},
  "mass-suggestion": {"time":"Action","range":"60 feet","components":"V, M (a snake’s tongue)","duration":"24 hours","desc":"You suggest a course of activity—described in no more than 25 words—to twelve or fewer creatures you can see within range that can hear and understand you. The suggestion must sound achievable and not involve anything that would obviously deal damage to any of the targets or their allies. For example, you could say, “Walk to the village down that road, and help the villagers there harvest crops until sunset.” Or you could say, “Now is not the time for violence. Drop your weapons, and dance! Stop in an hour.”\n\nEach target must succeed on a Wisdom saving throw or have the Charmed condition for the duration or until you or your allies deal damage to the target. Each Charmed target pursues the suggestion to the best of its ability. The suggested activity can continue for the entire duration, but if the suggested activity can be completed in a shorter time, the spell ends for a target upon completing it.","higher":"Using a Higher-Level Spell Slot. The duration is longer with a spell slot of level 7 (10 days), 8 (30 days), or 9 (366 days).","verbatim":true,"source":"SRD 5.2.1 p.148","checked":true,"note":""},
  "move-earth": {"time":"Action","range":"120 feet","components":"V, S, M (a miniature shovel)","duration":"Concentration, up to 2 hours","desc":"Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area’s elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can’t exceed half the area’s largest dimension. For example, if you affect a 40-foot square, you can create a pillar up to 20 feet high, raise or lower the square’s elevation by up to 20 feet, dig a trench up to 20 feet deep, and so on. It takes 10 minutes for these changes to complete. Because the terrain’s transformation occurs slowly, creatures in the area can’t usually be trapped or injured by the ground’s movement.\n\nAt the end of every 10 minutes you spend concentrating on the spell, you can choose a new area of terrain to affect within range.\n\nThis spell can’t manipulate natural stone or stone construction. Rocks and structures shift to accommodate the new terrain. If the way you shape the terrain would make a structure unstable, it might collapse.\n\nSimilarly, this spell doesn’t directly affect plant growth. The moved earth carries any plants along with it.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.151","checked":true,"note":""},
  "otiluke-s-freezing-sphere": {"time":"Action","range":"300 feet","components":"V, S, M (a miniature crystal sphere)","duration":"Instantaneous","desc":"A frigid globe streaks from you to a point of your choice within range, where it explodes in a 60-foot-radius Sphere. Each creature in that area makes a Constitution saving throw, taking 10d6 Cold damage on failed save or half as much damage on a successful one.\n\nIf the globe strikes a body of water, it freezes the water to a depth of 6 inches over an area 30 feet square. This ice lasts for 1 minute. Creatures that were swimming on the surface of frozen water are trapped in the ice and have the Restrained condition. A trapped creature can take an action to make a Strength (Athletics) check against your spell save DC to break free.\n\nYou can refrain from firing the globe after completing the spell’s casting. If you do so, a globe about the size of a sling bullet, cool to the touch, appears in your hand. At any time, you or a creature you give the globe to can throw the globe (to a range of 40 feet) or hurl it with a sling (to the sling’s normal range). It shatters on impact, with the same effect as a normal casting of the spell. You can also set the globe down without shattering it. After 1 minute, if the globe hasn’t already shattered, it explodes.","higher":"Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 6.","verbatim":true,"source":"SRD 5.2.1 p.134","checked":true,"note":""},
  "sunbeam": {"time":"Action","range":"Self","components":"V, S, M (a magnifying glass)","duration":"Concentration, up to 1 minute","desc":"You launch a sunbeam in a 5-foot-wide, 60-foot-long Line. Each creature in the Line makes a Constitution saving throw. On a failed save, a creature takes 6d8 Radiant damage and has the Blinded condition until the start of your next turn. On a successful save, it takes half as much damage only.\n\nUntil the spell ends, you can take a Magic action to create a new Line of radiance.\n\nFor the duration, a mote of brilliant radiance shines above you. It sheds Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. This light is sunlight.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.166","checked":true,"note":""},
  "true-seeing": {"time":"Action","range":"Touch","components":"V, S, M (mushroom powder worth 25+ GP, which the spell consumes)","duration":"1 hour","desc":"For the duration, the willing creature you touch has Truesight with a range of 120 feet.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.171","checked":true,"note":""},
  "delayed-blast-fireball": {"time":"Action","range":"150 feet","components":"V, S, M (a ball of bat guano and sulfur)","duration":"Concentration, up to 1 minute","desc":"A beam of yellow light flashes from you, then condenses at a chosen point within range as a glowing bead for the duration. When the spell ends, the bead explodes, and each creature in a 20-foot-radius Sphere centered on that point makes a Dexterity saving throw. A creature takes Fire damage equal to the total accumulated damage on a failed save or half as much damage on a successful one.\n\nThe spell’s base damage is 12d6, and the damage increases by 1d6 whenever your turn ends and the spell hasn’t ended.\n\nIf a creature touches the glowing bead before the spell ends, that creature makes a Dexterity saving throw. On a failed save, the spell ends, causing the bead to explode. On a successful save, the creature can throw the bead up to 40 feet. If the thrown bead enters a creature’s space or collides with a solid object, the spell ends, and the bead explodes.\n\nWhen the bead explodes, flammable objects in the explosion that aren’t being worn or carried start burning.","higher":"Using a Higher-Level Spell Slot. The base damage increases by 1d6 for each spell slot level above 7.","verbatim":true,"source":"SRD 5.2.1 p.122","checked":true,"note":""},
  "etherealness": {"time":"Action","range":"Self","components":"V, S","duration":"Up to 8 hours","desc":"You step into the border regions of the Ethereal Plane, where it overlaps with your current plane. You remain in the Border Ethereal for the duration. During this time, you can move in any direction. If you move up or down, every foot of movement costs an extra foot. You can perceive the plane you left, which looks gray, and you can’t see anything there more than 60 feet away.\n\nWhile on the Ethereal Plane, you can affect and be affected only by creatures, objects, and effects on that plane. Creatures that aren’t on the Ethereal Plane can’t perceive or interact with you unless a feature gives them the ability to do so.\n\nWhen the spell ends, you return to the plane you left in the spot that corresponds to your space in the Border Ethereal. If you appear in an occupied space, you are shunted to the nearest unoccupied space and take Force damage equal to twice the number of feet you are moved.\n\nThis spell ends instantly if you cast it while you are on the Ethereal Plane or a plane that doesn’t border it, such as one of the Outer Planes.","higher":"Using a Higher-Level Spell Slot. You can target up to three willing creatures (including yourself) for each spell slot level above 7. The creatures must be within 10 feet of you when you cast the spell.","verbatim":true,"source":"SRD 5.2.1 p.128","checked":true,"note":""},
  "finger-of-death": {"time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","desc":"You unleash negative energy toward a creature you can see within range. The target makes a Constitution saving throw, taking 7d8 + 30 Necrotic damage on a failed save or half as much damage on a successful one.\n\nA Humanoid killed by this spell rises at the start of your next turn as a Zombie (see “Monsters”) that follows your verbal orders.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.131","checked":true,"note":""},
  "fire-storm": {"time":"Action","range":"150 feet","components":"V, S","duration":"Instantaneous","desc":"A storm of fire appears within range. The area of the storm consists of up to ten 10-foot Cubes, which you arrange as you like. Each Cube must be contiguous with at least one other Cube. Each creature in the area makes a Dexterity saving throw, taking 7d10 Fire damage on a failed save or half as much damage on a successful one.\n\nFlammable objects in the area that aren’t being worn or carried start burning.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.132","checked":true,"note":""},
  "plane-shift": {"time":"Action","range":"Touch","components":"V, S, M (a forked, metal rod worth 250+ GP and attuned to a plane of existence)","duration":"Instantaneous","desc":"You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. You can specify a target destination in general terms, such as a specific city on the Elemental Plane of Fire or palace on the second level of the Nine Hells, and you appear in or near that destination, as determined by the GM.\n\nAlternatively, if you know the sigil sequence of a teleportation circle on another plane of existence, this spell can take you to that circle. If the teleportation circle is too small to hold all the creatures you transported, they appear in the closest unoccupied spaces next to the circle.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.153","checked":true,"note":""},
  "prismatic-spray": {"time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","desc":"Eight rays of light flash from you in a 60-foot Cone. Each creature in the Cone makes a Dexterity saving throw. For each target, roll 1d8 to determine which color ray affects it, consulting the Prismatic Rays table.\n\nPrismatic Rays\n1d8 | Ray\n1 | Red. Failed Save: 12d6 Fire damage. Successful\nSave: Half as much damage.\n2 | Orange. Failed Save: 12d6 Acid damage. Successful\nSave: Half as much damage.\n3 | Yellow. Failed Save: 12d6 Lightning damage. Suc-\ncessful Save: Half as much damage.\n4 | Green. Failed Save: 12d6 Poison damage. Success-\nful Save: Half as much damage.\n1d8 | Ray\n5 | Blue. Failed Save: 12d6 Cold damage. Successful\nSave: Half as much damage.\n6 | Indigo. Failed Save: The target has the Restrained\ncondition and makes a Constitution saving throw\nat the end of each of its turns. If it successfully\nsaves three times, the condition ends. If it fails\nthree times, it has the Petrified condition until it\nis freed by an effect like the Greater Restoration\nspell. The successes and failures needn’t be con-\nsecutive; keep track of both until the target col-\nlects three of a kind.\n7 | Violet. Failed Save: The target has the Blinded\ncondition and makes a Wisdom saving throw at\nthe start of your next turn. On a successful save,\nthe condition ends. On a failed save, the condi-\ntion ends, and the creature teleports to another\nplane of existence (GM’s choice).\n8 | Special. The target is struck by two rays. Roll\ntwice, rerolling any 8.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.154","checked":true,"note":""},
  "project-image": {"time":"Action","range":"500 miles","components":"V, S, M (a statuette of yourself worth 5+ GP)","duration":"Concentration, up to 1 day","desc":"You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, regardless of intervening obstacles. The illusion looks and sounds like you, but it is intangible. If the illusion takes any damage, it disappears, and the spell ends.\n\nYou can see through the illusion’s eyes and hear through its ears as if you were in its space. As a Magic action, you can move it up to 60 feet and make it gesture, speak, and behave in whatever way you choose. It mimics your mannerisms perfectly.\n\nPhysical interaction with the image reveals it to be illusory, since things can pass through it. A creature that takes the Study action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.156","checked":true,"note":""},
  "regenerate": {"time":"1 minute","range":"Touch","components":"V, S, M (a prayer wheel)","duration":"1 hour","desc":"A creature you touch regains 4d8 + 15 Hit Points. For the duration, the target regains 1 Hit Point at the start of each of its turns, and any severed body parts regrow after 2 minutes.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.158","checked":true,"note":""},
  "reverse-gravity": {"time":"Action","range":"100 feet","components":"V, S, M (a lodestone and iron filings)","duration":"Concentration, up to 1 minute","desc":"This spell reverses gravity in a 50-foot-radius, 100foot high Cylinder centered on a point within range. All creatures and objects in that area that aren’t anchored to the ground fall upward and reach the top of the Cylinder. A creature can make a Dexterity saving throw to grab a fixed object it can reach, thus avoiding the fall upward.\n\nIf a ceiling or an anchored object is encountered in this upward fall, creatures and objects strike it just as they would during a downward fall. If an affected creature or object reaches the Cylinder’s top without striking anything, it hovers there for the duration. When the spell ends, affected objects and creatures fall downward.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.159","checked":true,"note":""},
  "symbol": {"time":"1 minute","range":"Touch","components":"V, S, M (powdered diamond worth 1,000+ GP, which the spell consumes)","duration":"Until dispelled or triggered","desc":"You inscribe a harmful glyph either on a surface (such as a section of floor or wall) or within an object that can be closed (such as a book or chest). The glyph can cover an area no larger than 10 feet in diameter. If you choose an object, it must remain in place; if it is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\n\nThe glyph is nearly imperceptible and requires a successful Wisdom (Perception) check against your spell save DC to notice.\n\nWhen you inscribe the glyph, you set its trigger and choose which effect the symbol bears: Death, Discord, Fear, Pain, Sleep, or Stunning. Each one is explained below.\n\nSet the Trigger. You decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, common triggers include touching or stepping on the glyph, removing another object covering it, or approaching within a certain distance of it. For glyphs inscribed within an object, common triggers include opening that object or seeing the glyph.\n\nYou can refine the trigger so that only creatures of certain types activate it (for example, the glyph could be set to affect Aberrations). You can also set conditions for creatures that don’t trigger the glyph, such as those who say a certain password.\n\nOnce triggered, the glyph glows, filling a 60-foot-radius Sphere with Dim Light for 10 minutes, after which time the spell ends. Each creature in the Sphere when the glyph activates is targeted by its effect, as is a creature that enters the Sphere for the first time on a turn or ends its turn there. A creature is targeted only once per turn.\n\nDeath. Each target makes a Constitution saving throw, taking 10d10 Necrotic damage on a failed save or half as much damage on a successful save.\n\nDiscord. Each target makes a Wisdom saving throw. On a failed save, a target argues with other creatures for 1 minute. During this time, it is incapable of meaningful communication and has Disadvantage on attack rolls and ability checks.\n\nFear. Each target must succeed on a Wisdom saving throw or have the Frightened condition for 1 minute. While Frightened, the target must move at least 30 feet away from the glyph on each of its turns, if able.\n\nPain. Each target must succeed on a Constitution saving throw or have the Incapacitated condition for 1 minute.\n\nSleep. Each target must succeed on a Wisdom saving throw or have the Unconscious condition for 10 minutes. A creature awakens if it takes damage or if someone takes an action to shake it awake.\n\nStunning. Each target must succeed on a Wisdom saving throw or have the Stunned condition for 1 minute.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.167","checked":true,"note":""},
  "teleport": {"time":"Action","range":"10 feet","components":"V","duration":"Instantaneous","desc":"This spell instantly transports you and up to eight willing creatures that you can see within range, or a single object that you can see within range, to a destination you select. If you target an object, it must be Large or smaller, and it can’t be held or carried by an unwilling creature.\n\nThe destination you choose must be known to you, and it must be on the same plane of existence as you. Your familiarity with the destination determines whether you arrive there successfully. The GM rolls 1d100 and consults the Teleportation Outcome table and the explanations after it.\n\nTeleportation Outcome\nSimilar Off On\nFamiliarity | Mishap | Area | Target | Target\nPermanent circle | — | — | — | 01–00\nLinked object | — | — | — | 01–00\nVery familiar | 01–05 | 06–13 | 14–24 | 25–00\nSeen casually | 01–33 | 34–43 | 44–53 | 54–00\nViewed once or 01–43 | 44–53 | 54–73 | 74–00\ndescribed\nFalse destination | 01–50 | 51–00 | — | —\n\nFamiliarity. Here are the meanings of the terms in the table’s Familiarity column:\n\n• “Permanent circle” means a permanent teleportation circle whose sigil sequence you know.\n• “Linked object” means you possess an object taken from the desired destination within the last six months, such as a book from a wizard’s library.\n• “Very familiar” is a place you have visited often, a place you have carefully studied, or a place you can see when you cast the spell.\n• “Seen casually” is a place you have seen more than once but with which you aren’t very familiar.\n• “Viewed once or described” is a place you have seen once, possibly using magic, or a place you know through someone else’s description, perhaps from a map.\n• “False destination” is a place that doesn’t exist. Perhaps you tried to scry an enemy’s sanctum but instead viewed an illusion, or you are attempting to teleport to a location that no longer exists.\n\nMishap. The spell’s unpredictable magic results in a difficult journey. Each teleporting creature (or the target object) takes 3d10 Force damage, and the GM rerolls on the table to see where you wind up (multiple mishaps can occur, dealing damage each time).\n\nSimilar Area. You and your group (or the target object) appear in a different area that’s visually or thematically similar to the target area. You appear in the closest similar place. If you are heading for your home laboratory, for example, you might appear in another person’s laboratory in the same city.\n\nOff Target. You and your group (or the target object) appear 2d12 miles away from the destination in a random direction. Roll 1d8 for the direction: 1, east; 2, southeast; 3, south; 4, southwest; 5, west; 6, northwest; 7, north; or 8, northeast.\n\nOn Target. You and your group (or the target object) appear where you intended.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.168","checked":true,"note":""},
  "animal-shapes": {"time":"Action","range":"30 feet","components":"V, S","duration":"24 hours","desc":"Choose any number of willing creatures that you can see within range. Each target shape-shifts into a Large or smaller Beast of your choice that has a Challenge Rating of 4 or lower. You can choose a different form for each target. On later turns, you can take a Magic action to transform the targets again.\n\nA target’s game statistics are replaced by the chosen Beast’s statistics, but the target retains its creature type; Hit Points; Hit Point Dice; alignment; ability to communicate; and Intelligence, Wisdom, and Charisma scores. The target’s actions are limited by the Beast form’s anatomy, and it can’t cast spells. The target’s equipment melds into the new form, and the target can’t use any of that equipment while in that form.\n\nThe target gains a number of Temporary Hit Points equal to the Hit Points of the first form into which it shape-shifts. These Temporary Hit Points vanish if any remain when the spell ends. The transformation lasts for the duration or until the target ends it as a Bonus Action.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.108","checked":true,"note":""},
  "control-weather": {"time":"10 minutes","range":"Self","components":"V, S, M (burning incense)","duration":"Concentration, up to 8 hours","desc":"You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell, and it ends early if you go indoors.\n\nWhen you cast the spell, you change the current weather conditions, which are determined by the GM. You can change precipitation, temperature, and wind. It takes 1d4 × 10 minutes for the new conditions to take effect. Once they do so, you can change the conditions again. When the spell ends, the weather gradually returns to normal.\n\nWhen you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction.\n\nPrecipitation\nStage | Condition\n1 | Clear\n2 | Light clouds\n3 | Overcast or ground fog\n4 | Rain, hail, or snow\n5 | Torrential rain, driving hail, or blizzard\nTemperature | Wind\nStage | Condition | Stage | Condition\n1 | Heat wave | 1 | Calm\n2 | Hot | 2 | Moderate wind\n3 | Warm | 3 | Strong wind\n4 | Cool | 4 | Gale\n5 | Cold | 5 | Storm\n6 | Freezing","higher":"","verbatim":true,"source":"SRD 5.2.1 p.120","checked":true,"note":""},
  "demiplane": {"time":"Action","range":"60 feet","components":"S","duration":"1 hour","desc":"You create a shadowy Medium door on a flat solid surface that you can see within range. This door can be opened and closed, and it leads to a demiplane that is an empty room 30 feet in each dimension, made of wood or stone (your choice).\n\nWhen the spell ends, the door vanishes, and any objects inside the demiplane remain there. Any creatures inside also remain unless they opt to be shunted through the door as it vanishes, landing with the Prone condition in the unoccupied spaces closest to the door’s former space.\n\nEach time you cast this spell, you can create a new demiplane or connect the shadowy door to a demiplane you created with a previous casting of this spell. Additionally, if you know the nature and contents of a demiplane created by a casting of this spell by another creature, you can connect the shadowy door to that demiplane instead.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.122","checked":true,"note":""},
  "dominate-monster": {"time":"Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 hour","desc":"One creature you can see within range must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The target has Advantage on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success.\n\nYou have a telepathic link with the Charmed target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as “Attack that creature,” “Move over there,” or “Fetch that object.” The target does its best to obey on its turn. If it completes an order and doesn’t receive further direction from you, it acts and moves as it likes, focusing on protecting itself.\n\nYou can command the target to take a Reaction but must take your own Reaction to do so.","higher":"Using a Higher-Level Spell Slot. Your Concentration can last longer with a level 9 spell slot (up to 8 hours).","verbatim":true,"source":"SRD 5.2.1 p.125","checked":true,"note":""},
  "earthquake": {"time":"Action","range":"500 feet","components":"V, S, M (a fractured rock)","duration":"Concentration, up to 1 minute","desc":"Choose a point on the ground that you can see within range. For the duration, an intense tremor rips through the ground in a 100-foot-radius circle centered on that point. The ground there is Difficult Terrain.\n\nWhen you cast this spell and at the end of each of your turns for the duration, each creature on the ground in the area makes a Dexterity saving throw. On a failed save, a creature has the Prone condition, and its Concentration is broken.\n\nYou can also cause the effects below.\n\nFissures. A total of 1d6 fissures open in the spell’s area at the end of the turn you cast it. You choose the fissures’ locations, which can’t be under structures. Each fissure is 1d10 × 10 feet deep and 10 feet wide, and it extends from one edge of the spell’s area to another edge. A creature in the same space as a fissure must succeed on a Dexterity saving throw or fall in. A creature that successfully saves moves with the fissure’s edge as it opens.\n\nStructures. The tremor deals 50 Bludgeoning damage to any structure in contact with the ground in the area when you cast the spell and at the end of each of your turns until the spell ends. If a structure drops to 0 Hit Points, it collapses.\n\nA creature within a distance from a collapsing structure equal to half the structure’s height makes a Dexterity saving throw. On a failed save, the creature takes 12d6 Bludgeoning damage, has the Prone condition, and is buried in the rubble, requiring a DC 20 Strength (Athletics) check as an action to escape. On a successful save, the creature takes half as much damage only.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.127","checked":true,"note":""},
  "incendiary-cloud": {"time":"Action","range":"150 feet","components":"V, S","duration":"Concentration, up to 1 minute","desc":"A swirling cloud of embers and smoke fills a 20-foot-radius Sphere centered on a point within range. The cloud’s area is Heavily Obscured. It lasts for the duration or until a strong wind (like that created by Gust of Wind) disperses it.\n\nWhen the cloud appears, each creature in it makes a Dexterity saving throw, taking 10d8 Fire damage on a failed save or half as much damage on a successful one. A creature must also make this save when the Sphere moves into its space and when it enters the Sphere or ends its turn there. A creature makes this save only once per turn.\n\nThe cloud moves 10 feet away from you in a direction you choose at the start of each of your turns.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.142","checked":true,"note":""},
  "maze": {"time":"Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 10 minutes","desc":"You banish a creature that you can see within range into a labyrinthine demiplane. The target remains there for the duration or until it escapes the maze.\n\nThe target can take a Study action to try to escape. When it does so, it makes a DC 20 Intelligence (Investigation) check. If it succeeds, it escapes, and the spell ends.\n\nWhen the spell ends, the target reappears in the space it left or, if that space is occupied, in the nearest unoccupied space.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.148","checked":true,"note":""},
  "mind-blank": {"time":"Action","range":"Touch","components":"V, S","duration":"24 hours","desc":"Until the spell ends, one willing creature you touch has Immunity to Psychic damage and the Charmed condition. The target is also unaffected by anything that would sense its emotions or alignment, read its thoughts, or magically detect its location, and no spell—not even Wish—can gather information about the target, observe it remotely, or control its mind.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.149","checked":true,"note":""},
  "power-word-stun": {"time":"Action","range":"60 feet","components":"V","duration":"Instantaneous","desc":"You overwhelm the mind of one creature you can see within range. If the target has 150 Hit Points or fewer, it has the Stunned condition. Otherwise, its Speed is 0 until the start of your next turn.\n\nThe Stunned target makes a Constitution saving throw at the end of each of its turns, ending the condition on itself on a success.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.154","checked":true,"note":""},
  "sunburst": {"time":"Action","range":"150 feet","components":"V, S, M (a piece of sunstone)","duration":"Instantaneous","desc":"Brilliant sunlight flashes in a 60-foot-radius Sphere centered on a point you choose within range. Each creature in the Sphere makes a Constitution saving throw. On a failed save, a creature takes 12d6 Radiant damage and has the Blinded condition for 1 minute. On a successful save, it takes half as much damage only.\n\nA creature Blinded by this spell makes another Constitution saving throw at the end of each of its turns, ending the effect on itself on a success.\n\nThis spell dispels Darkness in its area that was created by any spell.","higher":"","verbatim":true,"source":"SRD 5.2.1 p.167","checked":true,"note":""},
};
